class Kit:
    """The champion's ability slots (03 section 2.1, kits): camp / champion damage, CC, attack reset, the self-shield
    (Varg) and the ground area stun (Ryth). The dash slot is Nav's (30_nav)."""

    def __init__(self, me):
        """Slots by use: camp damage, champion damage, CC (ME['has_cc'] rule), attack reset."""
        self.me, self.rst = me, None
        self.ab = []
        self.shield_ab = self.gcc_ab = None     # [K1] self-shield slot (Varg); ground CC slot (Ryth's area stun)
        try:
            for a in self.me.abilities():
                info = a.info()
                if info is None:
                    continue
                aoe, dmg = a.is_aoe_damage(), a.is_damage()
                cc = a.is_cc() or (aoe and getattr(info, "duration", 0) > 0) or bool(getattr(info, "enhanced_attack", False))
                if a.is_shield():
                    self.shield_ab = a
                elif cc and a.can_target_ground() and not a.is_attack_reset() and not a.is_dash():
                    self.gcc_ab = a
                self.ab.append((a, (dmg or aoe) and a.can_target_camps(), (dmg or aoe or cc) and a.can_target_enemies(),
                                cc, a.is_attack_reset(), a.can_target_ground()))
        except Exception as e:
            trace("boot", "abilities " + err_text(e))

    def cast(self, target, camp):
        """One cast this turn on target (Unit) if a fitting slot is ready; False if none fired."""
        for a, on_camp, on_enemy, cc, reset, ground in self.ab:
            if camp and a is self.gcc_ab:
                continue                        # [K1] on camps the area stun is aimed by stun only
            if (on_camp if camp else (on_enemy or (cc and not reset))) and not reset:
                try:
                    if not a.is_ready():
                        continue
                    if a.use(target):
                        return True
                except Exception:
                    try:
                        if ground and a.use(target.position()):
                            return True
                    except Exception:
                        pass
        return False

    def reset_attack(self, target, pre=None, alts=()):
        """Attack-reset slots (self-cast), then a second basic attack. TRACE: `reset` line with the target's HP
        before my first hit (pre), at cast and right after the second attack() (verification, 15 Oct); the next
        turn's HP is traced by reset_check(). [K1] a target my first hit killed is swapped for the first
        live one of alts (in range); with none the reset is kept for a later turn (11% were wasted, ROLES.md)."""
        if _dead(target):
            target = next((u for u in alts if not _dead(u)), None)
            if target is None:
                return False
        for a, _c, _e, _cc, reset, _g in self.ab:
            if reset:
                try:
                    if a.is_ready() and a.use(None):
                        h0 = _uhp(target) if TRACE else 0
                        err = "-"
                        try:
                            ret = self.me.attack(target)
                            err = f"ret={ret}"
                        except Exception as e:
                            err = "raise " + err_text(e)[:80]
                        if TRACE:
                            h1 = _uhp(target)
                            self.rst = (target, pre, h0, cambc.round_number())
                            trace("reset", f"tgt={int(target)} pre={pre} cast={h0} after2={h1} str={self.me.strength():.0f} "
                                           f"{err} range={ME.get('range')}")
                        return True
                except Exception:
                    pass
        return False

    def reset_check(self):
        """TRACE only: the target's HP one turn after a reset cast (see reset_attack)."""
        rs = self.rst
        if rs is None:
            return
        self.rst = None
        t, pre, h0, r0 = rs
        trace("reset", f"next tgt={int(t)} pre={pre} cast={h0} now={_uhp(t)} rounds={cambc.round_number() - r0}")

    def shield(self, s, hit, extra=None):
        """[K1, strat/ROLES.md] the self-shield (Varg), one cast per turn [rules], when a hit is coming: an awake camp
        monster within its attack range (X1) (or extra, the camp I am about to hit) with no visible champion nearer than me (A2: the
        nearest is hit), or my HP dropped (hit) with a live monster in reach or an enemy attacker. True if cast."""
        a = self.shield_ab
        if a is None:
            return False
        try:
            if not a.is_ready() or self.me.buffs().has_shield():
                return False
        except Exception:
            return False
        why = "enemy" if hit and s.attacker is not None else None
        if why is None:
            others = [p for _c, p, _hp, _st in s.allies] + [e[1] for e in s.enemies]
            for lv in s.live.values():
                for c, hp, p, _st in lv:
                    d = p.chebyshev_distance(s.pos)
                    if hp <= 0 or d > crng(c) or (c is not extra and not _awake(c)):
                        continue
                    if hit or all(q.chebyshev_distance(p) >= d for q in others):
                        why = "camp"
                        break
                if why:
                    break
        if why is None:
            return False
        try:
            ok = a.use(None)
        except Exception as e:
            ok = False
            trace("kit", "shield " + err_text(e)[:60])
        if ok:
            trace("kit", f"shield {why} hp={s.hp:.0f}")
        return ok

    def stun(self, s, h, target, moved):
        """[K1, strat/ROLES.md; A22, A23 measured] the ground area stun (Ryth) on camps, before my attack (it excludes
        walking [rules]): the tile in its range whose radius-STUN_R square holds the most awake monsters (target counts:
        I am about to hit it). Never a tile that covers a sleeping monster of another group (it would wake it). True if
        cast."""
        a = self.gcc_ab
        if a is None or moved:
            return False
        try:
            if not a.is_ready():
                return False
            vt = a.valid_tiles()
        except Exception:
            return False
        aw, bad = [], []
        for g, lv in s.live.items():
            for c, hp, p, _st in lv:
                if hp > 0 and p.chebyshev_distance(s.pos) <= crng(c) + 2 * STUN_R + 2:
                    if c is target or _awake(c):
                        aw.append(p)
                    elif g != h:
                        bad.append(p)
        best = []
        seen = set()
        for p in aw:
            for q in [p] + [p + d for d in DIRS]:
                k = (q.x, q.y)
                if k in seen:
                    continue
                seen.add(k)
                try:
                    if not vt.is_set(q) or any(b.chebyshev_distance(q) <= STUN_R for b in bad):
                        continue
                except Exception:
                    continue
                n = sum(1 for m in aw if m.chebyshev_distance(q) <= STUN_R)
                best.append((-n, q.chebyshev_distance(s.pos), q.x, q.y))
        best.sort()
        for n, _d, x, y in best[:3]:
            try:
                if a.use(V(x, y)):
                    trace("kit", f"stun n={-n} at {x},{y} g{h}")
                    return True
            except Exception:
                pass
        return False


def shards_owned(c):
    """Shards bought so far: sum of item_count() weighted by _SHARD_W (built on first use from ItemType.result() /
    combine_count() [sdk]: an item that combines is a shard; the item it combines into counts that many)."""
    try:
        n = c.item_count()
    except Exception:
        return 0
    if len(_SHARD_W) != len(n):
        _SHARD_W[:] = [0] * len(n)
        for i in range(len(n)):
            try:
                it = cambc.ItemType(i)
                res = it.result()
                if res is not None:
                    _SHARD_W[i] = 1
                    j = int(res)
                    if 0 <= j < len(n):
                        _SHARD_W[j] = max(_SHARD_W[j], it.combine_count())
            except Exception:
                pass
    t = 0
    for i, k in enumerate(n):
        if k:
            t += k * _SHARD_W[i]
    return t


def build_target(c, build, alt=None):
    """First entry of `build` whose emblem is not complete: fewer than 5 (combine_count) of that shard and no emblem
    (the 5 shards combine into a separate item, ItemType.result() [sdk]). All complete: the last entry (shard stats
    stack, GameRules "Stats stack"). Returns (ItemType, item_count list or None)."""
    try:
        n = c.item_count()
    except Exception:
        return build[0], None
    for it in build:
        i = int(it)
        try:
            need = it.combine_count()
            res = it.result()
            j = int(res) if res is not None else -1
        except Exception:
            need, j = 5, -1
        if i < len(n) and n[i] >= need:
            continue
        if 0 <= j < len(n) and n[j] > 0:
            continue
        return it, n
    return alt_target(alt or (build[-1],), n), n


def alt_target(alt, n):
    """After the build: finish a started alt shard, else the alt family with the fewest emblems (ties: last)."""
    best, bc = alt[0], 1e9
    for it in alt:
        i = int(it)
        try:
            need, res = it.combine_count(), it.result()
            j = int(res) if res is not None else -1
        except Exception:
            need, j = 5, -1
        if i < len(n) and 0 < n[i] < need:
            return it
        c = n[j] if 0 <= j < len(n) else 0
        if c <= bc:                 # ties go to the later entry, so the pair alternates (DH, PS, DH, PS)
            best, bc = it, c
    return best


def apply_phase(w):
    """ME["prof"] = base row (ME["base"]) + the overrides of the phase for w.shards + my role's gold and build
    (ROLE_GOLD, ROLE_BUILD; after the spike shift the others' gold / shop are SPIKE_*); traces `phase` on change."""
    base = ME.get("base")
    role = getattr(w, "role", None) or "crew"     # before the World boots (or if it failed): the crew's
    if base is None:
        return
    ph = base.get("phases")
    spk = bool(getattr(w, "spike", False)) and role != "main"     # [user decision 15 Oct afternoon] the main carry unchanged
    i = 0
    for j, (th, _ov) in enumerate(ph or ()):
        if w.shards >= th:
            i = j
    if (i, spk, role) == w.phase:
        return
    p = dict(base)
    if ph:
        p.update(ph[i][1])
    p["gold"] = ROLE_GOLD[role]
    p["build"], p["alt"] = ROLE_BUILD[role]
    p["item"] = p["build"][0]
    if spk:
        p["gold"], p["shop"] = max(p["gold"], SPIKE_GOLD), SPIKE_SHOP
    ME["prof"] = p
    w.phase = (i, spk, role)
    trace("phase", f"{i} {role} shards={w.shards} gold={p['gold']} " + (" ".join(f"{k}={v}" for k, v in ph[i][1].items()) if ph else "")
          + (f" spike shop={SPIKE_SHOP}" if spk else ""))


def me_init():
    """Fill ME once (round 1). Traces fuel (tag me) and one facts line."""
    f0 = fuel()
    try:
        c = cambc.me()
        t = int(c.champion_name())
        d = _TYPE_TO_DRAFT[t] if 0 <= t < len(_TYPE_TO_DRAFT) else -1
        flags = {"has_cc": False, "has_dash": False, "has_heal": False, "has_shield": False, "has_aoe": False,
                 "attack_reset": False, "camp_spell": False}
        spell_range = None
        for a in c.abilities():
            info = a.info()
            if info is None:
                continue
            cc, dash, dmg, aoe = a.is_cc(), a.is_dash(), a.is_damage(), a.is_aoe_damage()
            # [measured 14 Oct] Ryth's area stun is AoeDamage with duration=1 (is_cc() False); Marcella's stun is
            # AttackReset with enhanced_attack=True. Both count as CC here.
            flags["has_cc"] |= cc or (aoe and getattr(info, "duration", 0) > 0) or bool(getattr(info, "enhanced_attack", False))
            flags["has_dash"] |= dash
            flags["has_heal"] |= a.is_heal()
            flags["has_shield"] |= a.is_shield()
            flags["has_aoe"] |= aoe
            flags["attack_reset"] |= a.is_attack_reset()
            flags["camp_spell"] |= (dmg or aoe) and a.can_target_camps()
            r = getattr(info, "range", None)          # dash and self-shield ranges are not spell ranges
            if r is not None and not dash and not a.is_shield() and (spell_range is None or r > spell_range):
                spell_range = r
        ME.update(flags)
        ME["base"] = TYPE_ROWS.get(t) or PROFILES.get(d, NEUTRAL)
        ME.update({"id": d, "type": t, "prof": ME["base"], "strength": c.strength(),
                   "hp": c.max_health(), "range": c.attack_range(), "focus": c.focus(),
                   "spell_range": spell_range, "passive": int(c.passive())})
    except Exception as e:
        trace("me", err_text(e))
        if "prof" not in ME:
            ME["prof"] = ME["base"] = NEUTRAL
    trace("me", f"fuel={f0 - fuel()}")
    if TRACE and "id" in ME:
        p = ME["prof"]
        trace("me", f"id={ME['id']} type={ME['type']} str={ME['strength']} hp={ME['hp']} range={ME['range']} "
                    f"focus={ME['focus']} spell_range={ME['spell_range']} passive={ME['passive']} "
                    + " ".join(k for k in ("has_cc", "has_dash", "has_heal", "has_shield", "has_aoe",
                                           "attack_reset", "camp_spell") if ME[k])
                    + " prof=" + ",".join(f"{p[k]}" for k in _KEYS))


# [strat/ROLES.md K2] every body buys along its build on any turn on the spawn tiles with >= 30 gold, not only on a
# SHOP trip. [K3] the camp damage a take costs me is priced after my mitigation (my_dmg): a finished Jungle emblem and
# my shield. [K4] one body captures (60_behaviors Farm reward branch, handoff).
def buy_all(w, s):
    """Buy shards along the profile's build: each buy goes to the first entry whose emblem is not complete
    (build_target, re-read after every buy so a finished emblem moves on to the next family). Trace per buy.
    ME["need"]: the gold that finishes the target's emblem (the SHOP window, 06 section 4.5)."""
    build = ME["prof"].get("build") or ROLE_BUILD["crew"][0]
    n = 0
    try:
        while n < 10:
            item, c = build_target(w.me, build, ME["prof"].get("alt") or ROLE_BUILD["crew"][1])
            ME["target"] = item
            if not w.me.can_buy(item):
                i = int(item)
                ME["need"] = item.cost() * (item.combine_count() - (c[i] if c and i < len(c) else 0))
                break
            w.me.buy(item)
            n += 1
            trace("shop", f"buy {item.name} gold={w.me.gold_count()}")
    except Exception as e:
        trace("err", "shop " + err_text(e))
    if n:
        mit_refresh(w)                          # [K3] a new Jungle emblem counts at once
    return n

# ---- 30_nav.py ----
"""Nav (docs/redo/05_PATHFINDING.md; 03_ARCHITECTURE.md section 2.1): every move and dash. Returns a status, never a
decision: "here" | "moved" | "blocked" | "waiting" | ("failed", reason).

L0 global goal fields over static blockers (walls, holes, altars, enemy spawn; camp tiles are NOT blockers: which
   camps live is dynamic), per key: "g<h>" tiles within my attack range of group h's camps, "c<h>" its spawn tiles,
   "a<i>" altar i's ring, "home"; LRU-capped, at most one new build a turn. Plus F_alt, F_enemy, F_home, and F_me
   with the walks gd / ad / near6 that Prices read.
L1 a waypoint K_WP steps down the global field (units ignored), then a local window compute_to(waypoint -> me) with
   units, live camps and danger as walls: Om Nom's Optimal Bug, our exact field as the bug walk. Fast path: nothing
   within FAST_R of the next FAST_N steps -> the global step.
L2 danger passes (Info, 35_info): camp_hit | enemy_hit, then camp_hit, then none (mode "fight": camp_hit, none).
L3 order(): set_priority, nearer my goal acts first, the capturer last.
L4 movement dash ("fast" walks, quiet rounds): 2 tiles down the field, then the step.
L5 a False move = an unseen champion in a bush: Mem, then the next candidate.
L6 progress monitor per goal: no gain STALL_RAND turns -> allies are walls 3 times in 4, STALL_SIDE -> a sidestep,
   STALL_FAIL -> ("failed", "stuck" | "osc"); 90_main's act fails the Behavior on it.
L7 tie-breaks among the window's optimal steps. L8 near the goal the window's roots are the goal's free tiles, so the
   bodies of a crew take distinct tiles; none free -> "waiting".
"""

FME_MOVE = 6                # rebuild F_me when I am more than this from its root
NAV_CACHE = 6               # goal fields kept (~31k memory each; ~0.77M fuel to build at 100x100 [measured 20 Oct])
GOAL_FUEL = 1_500_000       # a second goal-field build in one turn only above this fuel
K_WP = 8                    # GUESS: waypoint steps down the global field (05 L1)
WIN_EXTRA = 4               # window max distance = K_WP + this: the detour it can find (05 L1)
FAST_N, FAST_R = 3, 2       # GUESS: fast path when no unit / live camp / danger within FAST_R of the next FAST_N steps
STALL_RAND = 2              # GUESS: L6 no-gain turns before allies count as walls only 3 times in 4 (Gone Fishin)
STALL_SIDE = 4              # GUESS: ... before a sidestep (05 L6 said "another ring tile": L8 makes that automatic)
STALL_FAIL = 8              # GUESS: ... before ("failed", "stuck" | "osc")
MAXP = 100                  # L3 priority scale
ESCAPE_DASH = (1, 8)        # draft ids of Vesper and Ren: the dash is the escape, no movement dash with a bag (05 L4)
DASH_QUIET = 8              # no movement dash this many rounds after an enemy within DASH_QUIET_R (05 L4)
DASH_GAIN = 2               # a movement dash lands this much lower on the goal field: its full 2 tiles [rules]
DIRS = tuple(V(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1) if dx or dy)


class Nav:
    def __init__(self, w, terr, ab):
        """Round-1 fields (boot). w: the World (groups, altars, spawns, me)."""
        self.w = w
        self.hd = int(w.me)
        self.blk = terr | ab | w.esp            # L0: static walk blockers
        self.blk_dist = terr | w.esp            # F_me / F_enemy: altar and camp tiles passable (distances to them)
        nw = terr | terr.shift_right(1) | terr.shift_right(-1)
        self.nearw = (nw | nw.shift_up(1) | nw.shift_up(-1)) & ~terr     # L7: tiles along a wall
        self.goals, self.keys, self.cw = {}, [], set()
        self.built = -1
        self.moved, self.fail, self.last_step, self.lastp = False, None, "-", None
        self.wp = self.wpk = None
        self.mk, self.mbest, self.mn, self.mr, self.mpos = None, FAR, 0, -9, []
        self.lastv, self.prio = None, None
        self.n = [0] * 8                        # steps fast window pass>1 unit-blocked bush dash failed (tick `nav=`)
        rings = Bitboard()
        for a in w.apos:
            rings.draw_chebyshev(a, 1)
        rings &= ~self.blk
        self.F_alt = DistanceField()
        self.F_alt.compute(self.blk & ~rings, rings, Bitboard(), FAR - 1)
        self.F_enemy = DistanceField()
        self.F_enemy.compute(terr, w.esp, Bitboard(), FAR - 1)
        self.F_home = None
        self.dash_ab = None
        try:
            for a in w.me.abilities():
                if a.is_dash():
                    self.dash_ab = a            # dash_to (ground target, 2 tiles [rules])
        except Exception as e:
            trace("boot", "abilities " + err_text(e))

    def begin(self):
        """Turn start (90_main turn)."""
        self.moved, self.fail, self.lastv = False, None, None

    # ---- fields ----
    def build_fme(self, pos):
        """F_me from pos; gd/ad: walk distance to every group anchor / altar tile (stale until the next build)."""
        w = self.w
        f = DistanceField()
        b = Bitboard()
        b.set(pos)
        f.compute(self.blk_dist, b, Bitboard(), FAR - 1)
        self.F_me, self.fme_root = f, pos
        self.gd = {h: fget(f, w.G[h].anchor) for h in w.order}
        self.ad = [fget(f, a) for a in w.apos]
        self.near6 = sorted(w.order, key=lambda h: self.gd[h])[:6]

    def home_field(self):
        if self.F_home is None:
            self.F_home = DistanceField()
            self.F_home.compute(game_map.walls() | game_map.holes(), self.w.sp, Bitboard(), FAR - 1)
        return self.F_home

    def build(self, key, cw=False):
        """L0 goal field for key -> (field, roots). cw: the camp tiles are walls too (the window found no way past
        a camp: 05 L0's fallback)."""
        w = self.w
        k, blk = key[0], self.blk
        if k == "g":
            r = max(1, ME.get("range", 1))
            roots = Bitboard()
            for t in w.G[int(key[1:])].tiles:
                roots.draw_chebyshev(t, r)
            roots &= ~(blk | w.ctiles)          # never a spawn tile: an occupied one delays the respawn [rules]
        elif k == "c":
            roots = Bitboard()
            for t in w.G[int(key[1:])].tiles:
                roots.set(t)
        elif k == "a":
            roots = disk(w.apos[int(key[1:])], 1) & ~blk
        else:
            roots = w.sp & ~blk
        walls = (blk | w.ctiles) if cw else blk
        f = DistanceField()
        f.compute(walls & ~roots, roots, Bitboard(), FAR - 1)
        if key not in self.goals:
            self.keys.append(key)
            if len(self.keys) > NAV_CACHE:
                old = self.keys.pop(0)
                self.goals.pop(old, None)
                self.cw.discard(old)
        self.goals[key] = g = (f, roots)
        if self.wpk == key:
            self.wpk = None
        return g

    def goal(self, key, r):
        """Cached goal field, else built (at most one build a turn below GOAL_FUEL); None: not this turn."""
        g = self.goals.get(key)
        if g is not None:
            return g
        if self.built == r and fuel() < GOAL_FUEL:
            return None
        self.built = r
        return self.build(key)

    def walk_to(self, key, pos):
        """Exact walk if key's goal field is cached, else None."""
        g = self.goals.get(key)
        return None if g is None else fget(g[0], pos)

    # ---- dashes ----
    def dash_to(self, s, key, kind):
        """Dash (the is_dash slot, if ready) to the valid free tile with the lowest key(q) (None = not a candidate);
        tries the best 4 (use() returns False on an unseen occupant, raises on a known bad tile). On success s.pos is
        the landing tile; traces `dash`. True if I dashed."""
        a = self.dash_ab
        try:
            if a is None or not a.is_ready():
                return False
            vt = a.valid_tiles() & ~(self.blk | INFO.units() | INFO.camps())
        except Exception:
            return False
        cand = sorted((k, q.x, q.y) for q in vt.positions() for k in (key(q),) if k is not None)
        for _k, x, y in cand[:4]:
            try:
                if a.use(V(x, y)):
                    trace("dash", f"{kind} {s.pos.x},{s.pos.y}->{x},{y}")
                    s.pos = V(x, y)
                    self.moved = True
                    self.n[6] += 1
                    return True
                MEM.note_bush(V(x, y), s.r)
            except Exception:
                pass
        return False

    def escape(self, s, ne):
        """ESCAPE: an enemy within 2 -> dash to the tile farthest from the nearest enemy (capped 7), ties down the
        home field."""
        if s.near_e <= 2 and self.dash_ab is not None:
            hf = self.home_field()
            self.dash_to(s, lambda q: (-min(7, min(q.chebyshev_distance(p) for p in ne)), fget(hf, q)), "escape")

    # ---- moves ----
    def try_moves(self, s, cands, units):
        """Move to the first candidate that works. A False is a hidden champion in a bush [rules]: Mem notes it (L5)
        and the next candidate is tried this turn. Known-occupied tiles (units) are skipped: they raise [rules]."""
        w = self.w
        for q in cands:
            if not (0 <= q.x < w.Wm and 0 <= q.y < w.Hm) or units.is_set(q) or self.blk.is_set(q):
                continue
            try:
                ok = w.me.move_absolute(q)
            except Exception:
                continue
            if ok:
                self.moved = True
                self.lastp = q
                return True
            MEM.note_bush(q, s.r)
            units.set(q, True)
            self.n[5] += 1
        return False

    def coin(self, s, q):
        """1 time in 4, different per body, round and tile (L6: Gone Fishin's 25 % ally-as-empty)."""
        return (self.hd * 7919 + s.r * 104729 + q.x * 31 + q.y * 17) % 4 == 0

    def passes(self, mode, skip):
        """L2: the danger boards, one per pass, the empty ones dropped; None = no danger."""
        if mode == "raw":
            return [None]
        ch = INFO.camp_hit(skip)
        out = []
        if mode != "fight":
            eh = INFO.enemy_hit()
            if not eh.is_empty():
                out.append(ch | eh)
        if not ch.is_empty():
            out.append(ch)
        out.append(None)
        return out

    def window(self, s, roots, passes, units, md):
        """L1/L2: compute_to(roots -> me) with units, live camps and each pass's danger as walls -> (field, pass index)
        or (None, -1). L6: after STALL_RAND no-gain turns, allies are walls only 3 times in 4."""
        pos = s.pos
        uw = units
        if self.mn >= STALL_RAND:
            uw = units.copy()
            for _c, p, _hp, _st in s.allies:
                if self.coin(s, p):
                    uw.set(p, False)
        base = self.blk | uw | INFO.camps()
        dest = Bitboard()
        dest.set(pos)
        for i, dz in enumerate(passes):
            walls = base | dz if dz is not None else base.copy()
            walls.set(pos, False)
            rt = roots & ~walls
            if rt.is_empty():
                continue
            g = DistanceField()
            g.compute_to(walls, rt, dest, Bitboard(), md)
            if fget(g, pos) < FAR:
                return g, i
        return None, -1

    def order_steps(self, s, g, f, dz):
        """L7: the window's optimal steps, best first: outside danger, lower global value, not on the map edge or along
        a wall (unless the goal is there), orthogonal, farther from the nearest ally."""
        pos, w = s.pos, self.w
        cands = [pos + d for d in g.next_moves_from(pos)]
        if len(cands) < 2:
            return cands
        key = []
        for q in cands:
            gv = fget(f, q) if f is not None else 0
            edge = gv > 0 and (q.x in (0, w.Wm - 1) or q.y in (0, w.Hm - 1) or self.nearw.is_set(q))
            ad = min((p.chebyshev_distance(q) for _c, p, _hp, _st in s.allies), default=3)
            key.append((dz is not None and dz.is_set(q), gv, edge, q.x != pos.x and q.y != pos.y, -min(ad, 3), q.x, q.y))
        key.sort()
        return [V(k[5], k[6]) for k in key]

    def monitor(self, s, key, v):
        """L6: no-gain turns on this goal (a new goal, or 2+ rounds without a step on it, starts again)."""
        pos = s.pos
        if key != self.mk or s.r - self.mr > 2:
            self.mk, self.mbest, self.mn, self.mpos = key, v, 0, []
        elif v < self.mbest:
            self.mbest, self.mn = v, 0
        else:
            self.mn += 1
        self.mr = s.r
        self.mpos = (self.mpos + [pos])[-4:]
        return self.mn

    def failed(self, s, key, v):
        m = self.mpos
        why = "osc" if len(m) == 4 and m[0] == m[2] and m[1] == m[3] and m[0] != m[1] else "stuck"
        trace("nav", f"failed {why} {key} v={v} best={self.mbest} n={self.mn} {s.pos.x},{s.pos.y}")
        self.fail, self.mk = why, None
        self.n[7] += 1
        return ("failed", why)

    def sidestep(self, s, f, v, units):
        """L6: any free neighbour no more than one worse on the global field, in a per-body order."""
        pos = s.pos
        cand = []
        for d in DIRS:
            q = pos + d
            u = fget(f, q)
            if u <= v + 1:
                cand.append((u, not self.coin(s, q), q.x, q.y))
        cand.sort()
        return self.try_moves(s, [V(x, y) for _u, _c, x, y in cand], units)

    def step(self, s, key, mode="safe"):
        """One step towards goal key. mode: "safe" (danger passes 1 -> 3), "fast" (safe + the movement dash),
        "fight" (camp danger only), "raw" (no danger)."""
        self.n[0] += 1
        if not s.can_move:
            return "blocked"
        g = self.goal(key, s.r)
        if g is None:
            return "blocked"
        f, roots = g
        v = fget(f, s.pos)
        if v == 0:
            self.mk, self.lastv = None, 0
            return "here"
        if v >= FAR:
            return "blocked"
        if self.monitor(s, key, v) >= STALL_FAIL:
            return self.failed(s, key, v)
        skip = int(key[1:]) if key[0] in "gc" else None     # the take's own group is not danger for its crew (05 L2)
        # L4: quiet rounds only; Vesper / Ren keep the dash (their escape) while carrying [05 L4]
        if mode == "fast" and v > 2 and self.dash_ab is not None and s.r - MEM.loud > DASH_QUIET \
                and not (s.bag > 0 and ME.get("id") in ESCAPE_DASH):
            ch = INFO.camp_hit(skip)
            if self.dash_to(s, lambda q: None if ch.is_set(q) else (lambda u: u if u <= v - DASH_GAIN else None)(fget(f, q)),
                            "traverse"):
                v = fget(f, s.pos)
                if v == 0:
                    self.lastv = 0
                    return "moved"
        units = INFO.units()
        passes = self.passes(mode, skip)
        pos = s.pos
        d0 = f.next_move_from(pos)
        q0 = pos + d0 if d0 is not None else None
        if q0 is not None and units.is_set(q0):
            self.n[4] += 1                      # L3 measure: a unit stands on my global optimal step
        if q0 is not None and self.mn < STALL_RAND:             # fast path
            box = disk(q0, FAST_R)
            q = q0
            for _ in range(FAST_N - 1):
                d = f.next_move_from(q)
                if d is None:
                    break
                q = q + d
                box.draw_chebyshev(q, FAST_R)
            obs = units | INFO.camps()
            if passes[0] is not None:
                obs |= passes[0]
            if (box & obs).is_empty() and self.try_moves(s, [q0], units):
                self.n[1] += 1
                self.lastv = v - 1
                self.last_step = f"{key} v={v} fast"
                return "moved"
        # L1 waypoint; L8 near the goal: the goal's tiles in the window are the roots
        wp = self.wp
        if self.wpk != key or wp is None or wp.chebyshev_distance(pos) <= 3 or fget(f, wp) >= v:
            q = pos
            for _ in range(K_WP):
                d = f.next_move_from(q)
                if d is None:
                    break
                q = q + d
            self.wp = wp = q
            self.wpk = key
        md = K_WP + WIN_EXTRA
        wr = roots & disk(pos, md) if fget(f, wp) == 0 else disk(wp, 1)
        gw, i = self.window(s, wr, passes, units, md)
        if gw is not None:
            self.n[2] += 1
            if i > 0:
                self.n[3] += 1
            if self.try_moves(s, self.order_steps(s, gw, f, passes[0]), units):
                self.lastv = fget(f, self.lastp)
                self.last_step = f"{key} v={v} win{i}"
                return "moved"
        elif fget(f, wp) == 0 and (wr & ~(self.blk | units | INFO.camps())).is_empty():
            self.last_step = f"{key} v={v} waiting"
            return "waiting"                    # L8: every goal tile near me is taken (Gone Fishin's congested well)
        elif key not in self.cw and not (INFO.camps() & disk(pos, md)).is_empty() and fuel() > GOAL_FUEL:
            self.cw.add(key)                    # L0 fallback: the global path runs into live camps the window can't pass
            self.build(key, True)
            trace("nav", f"camp walls {key} v={v}")
        if self.mn >= STALL_SIDE and self.sidestep(s, f, v, units):
            self.lastv = fget(f, self.lastp)
            self.last_step = f"{key} v={v} side"
            return "moved"
        self.last_step = f"{key} v={v} blocked n={self.mn}"
        return "blocked"

    def near(self, s, tiles, r, mode="safe", skip=None):
        """One step towards the tiles within r of tile(s) (r = 0: onto them): the window alone (no global field), as
        far as it takes. For goals that move or live in vision (a chase, an ally, a live monster, a peek)."""
        self.n[0] += 1
        if not s.can_move:
            return "blocked"
        pos = s.pos
        roots = Bitboard()
        for t in (tiles if isinstance(tiles, list) else (tiles,)):
            if r:
                roots.draw_chebyshev(t, r)
            else:
                roots.set(t)
        roots &= ~self.blk
        if roots.is_set(pos):
            return "here"
        units = INFO.units()
        passes = self.passes(mode, skip)
        gw, i = self.window(s, roots, passes, units, FAR - 1)
        if gw is None:
            return "blocked"
        self.n[2] += 1
        if i > 0:
            self.n[3] += 1
        return "moved" if self.try_moves(s, self.order_steps(s, gw, None, passes[0]), units) else "blocked"

    def away(self, s, pts, cap=7):
        """One step that keeps the min distance to pts (enemies, or monsters in range) as large as possible, capped at
        cap, and among those the lowest home-field value (towards spawn)."""
        if not s.can_move:
            return "blocked"
        hf = self.home_field()
        pos, w = s.pos, self.w
        units, camps = INFO.units(), INFO.camps()
        cand = []
        for dv in DIRS:
            q = pos + dv
            if not (0 <= q.x < w.Wm and 0 <= q.y < w.Hm) or self.blk.is_set(q) or units.is_set(q) or camps.is_set(q):
                continue
            de = min(q.chebyshev_distance(p) for p in pts)
            cand.append((-min(de, cap), fget(hf, q), q.x, q.y))
        cand.sort()
        return "moved" if self.try_moves(s, [V(x, y) for _d, _h, x, y in cand[:3]], units) else "blocked"

    def order(self, w, s):
        """L3 (Gone Fishin's formation through turn order): the body nearest its goal acts first next round and
        clears the way for those behind; the capturer acts last, so the others have left the spawn tiles [rules:
        higher priority acts first within the team, from the next round]."""
        p = 0 if w.capt else (MAXP - min(self.lastv, MAXP - 1)) if self.lastv is not None else None
        if p is not None and p != self.prio:
            try:
                w.me.set_priority(p)
                self.prio = p
            except Exception as e:
                trace("nav", "set_priority " + err_text(e))

# ---- 35_info.py ----
"""Mem and Info, started by doc 05 (L2, L5) with only what Nav reads; doc 07 extends them (the micro matrix, P-h).

Mem: what persists beyond vision: enemies last seen (round, tile, attack range), bush tiles a failed move found
occupied (05 L5), the last round an enemy was seen within DASH_QUIET_R (Nav's movement-dash gate, 05 L4).
Info: this turn's boards, built lazily and cached for the turn (Info.begin): units, live camp tiles, camp_hit,
enemy_hit (visible enemies + Mem's memory board). Nav uses them as walls (05 L2 passes); doc 07 adds per-tile facts.
"""

MEM_E = 2                   # rounds a vanished enemy stays in the memory board (05 L2)
BUSH_AGE = 3                # GUESS: rounds a bush found occupied stays a wall and a danger (05 L5)
BUSH_R = 2                  # GUESS: reach of the unseen champion in that bush: a step + melee range
E_NEAR = 4                  # enemy_hit: the nearest 4 visible enemies (05 L2)
DASH_QUIET_R = 12           # an enemy within this marks the round loud (05 L4)


class Mem:
    __slots__ = ("seen", "bush", "loud")

    def __init__(self):
        self.seen, self.bush, self.loud = {}, {}, -99     # handle -> (round, tile, range); (x, y) -> round

    def update(self, s):
        """Once a turn, after sense: record the visible enemies, forget the old entries."""
        r = s.r
        for e in s.enemies:
            self.seen[int(e[0])] = (r, e[1], arng(e[0]))
            if e[4] <= DASH_QUIET_R:
                self.loud = r
        for k in [k for k, v in self.seen.items() if r - v[0] > MEM_E]:
            del self.seen[k]
        for k in [k for k, v in self.bush.items() if r - v > BUSH_AGE]:
            del self.bush[k]

    def note_bush(self, q, r):
        """A move onto q returned False: an unseen champion stands in that bush [rules] (05 L5)."""
        self.bush[(q.x, q.y)] = r
        self.loud = r


class Info:
    __slots__ = ("w", "s", "_units", "_camps", "_hit", "_ehit")

    def begin(self, w, s):
        self.w, self.s = w, s
        self._units = self._camps = self._ehit = None
        self._hit = {}

    def units(self):
        """Visible champions of both teams [sdk champion_tiles], my tile cleared, plus Mem's occupied bushes."""
        if self._units is None:
            b = vision.champion_tiles()
            b.set(self.s.pos, False)
            for (x, y) in MEM.bush:
                b.set(V(x, y), True)
            self._units = b
        return self._units

    def camps(self):
        """Tiles of live camps in vision (awake | asleep: both exclude dead camps [sdk])."""
        if self._camps is None:
            self._camps = vision.awake_camp_tiles() | vision.asleep_camp_tiles()
        return self._camps

    def camp_hit(self, skip=None):
        """Tiles within its own attack range of an awake monster in vision (X1: 3 / 4 / 5 [sdk attack_range]), the
        group `skip` (the take this body is on) left out. Approximation (05 section 8): an ally nearer the monster is
        not counted, so the board over-counts tiles where the ally would be hit instead."""
        b = self._hit.get(skip)
        if b is None:
            b = Bitboard()
            aw = vision.awake_camp_tiles()
            if not aw.is_empty():
                ti = self.w.tinfo
                for q in aw.positions():
                    h, rg = ti.get((q.x, q.y), (None, 5))
                    if skip is None or h != skip:
                        b.draw_chebyshev(q, rg)
            self._hit[skip] = b
        return b

    def enemy_hit(self):
        """Tiles a visible enemy can hit next round: its 1-step reach dilated by its attack range, as a Chebyshev disk
        of 1 + range (walls ignored: safe side); a dash is not modelled (05 section 8). Plus the memory board: an enemy
        seen MEM_E rounds ago, grown by a step a round; a bush found occupied, BUSH_R."""
        if self._ehit is None:
            b = Bitboard()
            s = self.s
            for e in sorted(s.enemies, key=lambda e: e[4])[:E_NEAR]:
                b.draw_chebyshev(e[1], 1 + arng(e[0]))
            r = s.r
            for (rs, p, rg) in MEM.seen.values():
                if rs < r:
                    b.draw_chebyshev(p, 1 + (r - rs) + rg)
            for (x, y) in MEM.bush:
                b.draw_chebyshev(V(x, y), BUSH_R)
            self._ehit = b
        return self._ehit


MEM = Mem()
INFO = Info()

# ---- 40_comms.py ----
"""Comms codec (docs/redo/04_COMMS.md, 03_ARCHITECTURE.md section 2.1): the 8 shared bytes (class Comms: decode into
the Snap each turn, encode from the current choice) and the draft record (1,024 bytes, written by 80_draft
DraftModel.encode, read once at boot by draft_decode). Layout: strat/MEMORY_LAYOUT.md.

Option codes (shared byte, low 3 bits; Behavior.code in 60_behaviors): 0 idle (also heal and fall, target 0; fall was
8, which overflowed into the target bits: docs/redo/04_COMMS.md section 2; tests/test_comms.py), 1 farm, 2 bank, 3 kill
(also hunt, target 31), 4 hold, 5 shop, 6 join, 7 dead; target in the high 5 bits (group index in draft-memory order, altar index, enemy handle & 31, ally slot for join).
Byte 5: enemy sighting, high 3 bits = enemies seen together (within SIGHT_R of one of them, capped 7; 0 = none), low
5 bits = (round // 4) & 31 when seen. Byte 6: the sighting's region, index of the altar nearest the cluster.
A reader treats age >= SIGHT_LIVE rounds as stale and clears byte 5. Byte 7: group death marker (mark_death).
"""

GRID = 10
REGIMES = ("few", "pick", "many")
BANKS = ("safe", "contested", "away")
MEM_VERSION = 2             # 2: group records carry d_us, d_them (strat/MEMORY_LAYOUT.md)
DEATH_MARK = 100            # rounds the team avoids a group an ally died farming (byte 7)
SIGHT_LIVE = 32             # rounds a sighting stays in byte 5 (readers clear it after; the stamp wraps at 128)
SIGHT_OVER = 12             # a weaker sighting overwrites a stronger one older than this
SIGHT_R = 8                 # enemies within this of each other count as seen together


def draft_decode(mem):
    """Draft memory -> dict (the play side). Layout (strat/MEMORY_LAYOUT.md): header 16 B, altars 3 B (side, x, y),
    groups 6 B (handle, side | bodies << 2, block, nearest altar, d_us, d_them; 255 = unreached), blocks 3 B (altar, side | recall << 2, traffic),
    (byte 10, the old ward count, is 0 since session 3: the draft's ward stage was deleted), danger 50 B (10x10 nibbles) when flag 64."""
    m = bytes(mem)
    if len(m) < 16 or m[0] != MEM_VERSION:
        return None
    d = dict(W=m[1], H=m[2], S=m[3], regime=m[4] & 3, bank=m[4] >> 2 & 3, bank_altar=m[5], flags=m[6],
             rich=m[11], a0=m[12], traffic_min=m[13], solo=m[14] / 255, ggems=m[15] / 255)
    k = 16
    d["altars"] = [(m[k + 3 * i], m[k + 3 * i + 1], m[k + 3 * i + 2]) for i in range(m[7])]
    k += 3 * m[7]
    d["groups"] = [(m[k + 6 * i], m[k + 6 * i + 1] & 3, m[k + 6 * i + 1] >> 2, m[k + 6 * i + 2], m[k + 6 * i + 3],
                    m[k + 6 * i + 4], m[k + 6 * i + 5]) for i in range(m[8])]
    k += 6 * m[8]
    d["blocks"] = [(m[k + 3 * i], m[k + 3 * i + 1] & 3, m[k + 3 * i + 1] >> 2 & 1, m[k + 3 * i + 2])
                   for i in range(m[9])]
    k += 3 * m[9]
    d["danger"] = [m[k + j // 2] >> (4 * (j & 1)) & 15 for j in range(GRID * GRID)] if d["flags"] & 64 else None
    d["bytes"] = k = k + (GRID * GRID // 2 if d["danger"] else 0)
    return d


def summary(d):
    """One line, identical in content to tools/mapmodel.py's SUMMARY line (diffed)."""
    S = max(1, d["S"])
    alt = "".join("octu"[a[0]] for a in d["altars"])
    ca = [alt.count(ch) for ch in "oct"]
    grp = ",".join(f"{'octu'[g[1]]}{g[2]}" for g in d["groups"])
    ba = "-" if d["bank_altar"] == 255 else f"A{d['bank_altar']}"
    return (f"SUMMARY {d['W']}x{d['H']} S={d['S']} regime={(REGIMES + ('?',))[d['regime']]} "
            f"altars={ca[0]}/{ca[1]}/{ca[2]} bank={(BANKS + ('?',))[d['bank']]} bank_altar={ba} "
            f"rich={d['rich']}/{S}={d['rich'] / S:.2f} altar_sides={alt} groups={grp} "
            f"solo={d.get('solo', 1.0):.2f} ggems={d.get('ggems', 0.0):.2f}")


class Comms:
    """The 8 shared bytes. decode fills the Snap, encode writes my slot and the sighting, mark_death byte 7."""

    @staticmethod
    def decode(w, s):
        """s.mem (raw), s.slots ((op, target) per slot 0-4), the sighting (s.sc count, s.sa region altar, s.sage age
        in rounds, s.stack), s.dead_g (the group an ally died farming within DEATH_MARK rounds, or None)."""
        r = s.r
        s.mem = m = bytearray(8)
        try:
            cambc.shared_memory.read(0, m)
        except Exception:
            pass
        s.slots = tuple((b & 7, b >> 3) for b in m[:5])
        sb = m[5]                               # sighting: count, region altar, age in rounds (4-round stamp)
        s.sc, s.sa = sb >> 5, m[6]
        s.sage = (((r // 4) - (sb & 31)) & 31) * 4 if s.sc else 999
        s.stack = s.sc >= stack_n(w) and s.sage <= SIGHT_FRESH and s.sa < len(w.apos)
        b7 = m[7]                               # death marker: group index + 1 (low 5 bits), (round // 32) & 7 stamp
        s.dead_g = (w.idx.get((b7 & 31) - 1) if b7 & 31 and (((r // 32) - (b7 >> 5)) & 7) * 32 < DEATH_MARK
                    else None)

    @staticmethod
    def claims(w, s):
        """{group handle: allies broadcasting farm on it}, {slot: (opt, tgt)}."""
        cl, by = {}, {}
        for k in range(5):
            if k == w.slot:
                continue
            op, tg = by[k] = s.slots[k]
            if op == 1 and tg in w.idx:
                h = w.idx[tg]
                cl[h] = cl.get(h, 0) + 1
        return cl, by

    @staticmethod
    def encode(w, s, beh):
        """My byte (slot) from Behavior beh (code | target bits << 3) when it changed; bytes 5-6 sighting (count | stamp,
        region altar); stale bytes 5 and 7 cleared."""
        code = beh.code
        b = code | (beh.target_bits(w, w.cur[1]) << 3 if 0 < code < 7 else 0)
        if b != w.sent and w.slot < 5:              # a sixth body (06 section 11.3) has no byte
            try:
                cambc.shared_memory[w.slot] = b
                w.sent = b
            except Exception:
                pass
        if not s.alive:
            return
        try:
            if s.sc and s.sage >= SIGHT_LIVE:
                cambc.shared_memory[5] = 0
                s.sc, s.sage = 0, 999
            b7 = s.mem[7]
            if b7 & 31 and (((s.r // 32) - (b7 >> 5)) & 7) * 32 >= DEATH_MARK:
                cambc.shared_memory[7] = 0
        except Exception:
            pass
        es = s.enemies
        if len(es) >= 2 and w.apos:
            # enemies seen together (my vision + my ward's): the largest count within SIGHT_R of one of them
            best, bp = 0, None
            for e in es:
                p = e[1]
                n = 0
                for f in es:
                    if p.chebyshev_distance(f[1]) <= SIGHT_R:
                        n += 1
                if n > best:
                    best, bp = n, p
            best = min(7, best)
            if best >= 2 and (best >= s.sc or s.sage > SIGHT_OVER):
                a = min(range(len(w.apos)), key=lambda i: bp.chebyshev_distance(w.apos[i]))
                nb = best << 5 | ((s.r // 4) & 31)
                if nb != s.mem[5] or a != s.mem[6]:
                    try:
                        cambc.shared_memory[5] = nb
                        cambc.shared_memory[6] = min(a, 254)
                    except Exception:
                        pass

    @staticmethod
    def mark_death(mi, r):
        """Byte 7: I died farming group index mi (index + 1, (round // 32) & 7 stamp); the team avoids it."""
        try:
            cambc.shared_memory[7] = (mi + 1) | ((r // 32) & 7) << 5
        except Exception:
            pass

# ---- 50_prices.py ----
"""Sense (Snap) and price the options (strat/PRICES.md) in team gems per round; 70_updaters chooses. The 8 shared
bytes are read and written by Comms (40_comms).
"""

KEEP_HP = 0.4               # [guess] the hit body keeps >= 40 % of max HP (KEEP_FRAC)
HYST = 1.2                  # switch only when a new option beats the current one by 20 %
KILL_PL_POWS = {0.6: 0.756, 0.95: 0.231}    # KILL value x (1 - pl) ** pow, pow = ln(0.5) / ln(1 - kill_plose): the factor
KILL_PL_POW = 0.756                         # is 0.5 at pl = kill_plose (no math module: precomputed; other kp -> this)
EXCL = 20                   # rounds an (option, target) is excluded after a timeout / failure
DENIAL = 24                 # default of the profile key `denial` (Vesper 60, 20_champs); [measured-ish] their farm rate 0.4 g/r x 60 rounds out (PRICES KILL)
THEIR_RATE = 0.4            # [guess] their gems per round per body (HOLD value 30 x 0.4)
P_NEAR = 0.5                # [guess] P(lose the bag) with an enemy within 8
DANGER_W = 0.2              # [guess] P(lose the bag) per unit of draft danger (cell value / 14)
SHOP_RETURN = True          # [deviation] SHOP rounds include the walk back from spawn to where I am
SURVIVE = 0.6               # [tuned] k bodies are enough if the most-hit body keeps > 40 % of its current HP
WAIT_PARTNER = 15           # [guess] rounds added to a pair take while the partner is not committed
# Group game [user plan 15 Oct, game type + pair/trio opener; all guess]: while stack_mode() (round < GROUP_UNTIL and the
# draft's solo share <= GROUP_SOLO_MAX) the team opens in subgroups (70_updaters opening_slots: trio + pair / two pairs /
# pair + solo), prices groups for its subgroup without the per-body split and never waits at a camp (60_behaviors Farm).
# One body captures in every mode (60_behaviors handoff, 06 section 1.2). GROUP_UNTIL 0 = off (behaviour unchanged).
