_PK = ("farm", "farm_their_side", "bank_risk", "kill_our_side", "kill_their_side", "hold", "shop", "join", "ward", "heal")


def _col(**kw):
    c = dict.fromkeys(_PK, 1.0)
    c.update(kw)
    return c


