class Join(Behavior):
    """Walk to an ally's farm (it broadcasts farm) or fight (it broadcasts kill); target = the ally's slot."""
    __slots__ = ()
    name, code = "join", 6

    def enter(self, w, s, tg):
        return (20, 0) if tg is not None else (0, 0)

    def target(self, w, s, tg):
        op, t = s.slots[tg] if tg < 5 else (0, 0)
        if op == 3:
            return next((a[1] for a in s.allies if w.ally_slot(a[0]) == tg), None)
        if op == 1 and t in w.idx:
            return w.G[w.idx[t]].anchor
        return None

    def progress(self, w, s, hit):
        return self.walkf(w, s)

    def execute(self, w, s, k):
        op, t = s.slots[k] if k < 5 else (0, 0)
        if op == 3:                             # a fight (50_prices JOIN a fight): walk to the ally, then KILL
            p = next((a[1] for a in s.allies if w.ally_slot(a[0]) == k), None)
            if p is None or p.chebyshev_distance(s.pos) <= 2:
                return "done"
            w.nav.near(s, p, 1)
            return "going"
        if op != 1 or t not in w.idx:
            return "failed"
        h = w.idx[t]
        if min(t.chebyshev_distance(s.pos) for t in w.G[h].tiles) <= 4:
            return "done"
        w.nav.step(s, f"g{h}")
        return "going"


class Heal(Behavior):
    """Recall (safe_recall steps out of camp range / away from enemies first); done on spawn at full HP, or at >= 0.9
    max HP once arrived. Standing on spawn heals to full at turn end [rules]."""
    __slots__ = ("arrived",)
    name, code = "heal", 0                      # broadcast as idle: the byte has no free code (7 is dead)

    def __init__(self):
        self.arrived = None

    def enter(self, w, s, tg):
        self.arrived = None
        return 10, 7                            # step out of reach, 5-turn recall, the heal turn on spawn

    def execute(self, w, s, _t):
        if not s.spawn:
            return safe_recall(w, s)
        if s.hp >= s.maxhp or (self.arrived is not None and s.hp >= 0.9 * s.maxhp):
            return "done"
        if self.arrived is None:
            self.arrived = s.r
        w.capt = True                           # healing on spawn: a deliberate stand
        return "going"


class Fall(Behavior):
    """Nothing priced above 0: fight the attacker when no flee can end (Kill.fight with my own chase counters),
    retreat, recall a bag or low HP, heal on spawn, else walk to the bank altar."""
    __slots__ = ("kd", "kn")
    name, code = "fall", 0                      # broadcast as idle, target 0 (was 8: overflowed into the target bits, 04_COMMS.md section 2)

    def __init__(self):
        self.kd, self.kn = 99, 0

    def enter(self, w, s, tg):
        self.kd, self.kn = 99, 0
        return 15, 0

    def execute(self, w, s, _t):
        if s.trapped and not flee_ok(s):
            return KILL.fight(w, s, int(s.attacker[0]), self, False)    # [ladder 5] no flee can end: fight the attacker
        near = [e for e in s.enemies if e[4] <= 4]
        if near and not s.spawn:
            if retreat_now(s):
                if s.near_e <= 3:               # retreat: out of their reach first, recall once clear
                    w.nav.escape(s, [e[1] for e in near])
                    w.nav.away(s, [e[1] for e in near])
                    return "going"
                return safe_recall(w, s)
        if (s.bag > 0 or s.hp < KEEP_HP * s.maxhp) and not s.spawn:
            return safe_recall(w, s)
        if s.spawn and s.hp < s.maxhp:
            w.capt = True                       # healing on spawn
            return "going"
        if w.bank < len(w.apos) and w.altar_open(w.bank):     # X8: never walk at a gated altar (Nav cannot reach it)
            w.nav.step(s, f"a{w.bank}")
        return "going"


class Dead(Behavior):
    """Out for 60 rounds [rules]: the dead gate in 90_main shops and broadcasts code 7."""
    __slots__ = ()
    name, code = "dead", 7


FARM, BANK, KILL, HUNT, HOLD, SHOP, JOIN, HEAL, FALL, DEAD = (Farm(), Bank(), Kill(), Hunt(), Hold(), Shop(), Join(),
                                                              Heal(), Fall(), Dead())
BEH = {b.name: b for b in (Behavior(), FARM, BANK, KILL, HUNT, HOLD, SHOP, JOIN, HEAL, FALL, DEAD)}


def prog_update(w, s, hit):
    """[IMPROVEMENTS 2, 15 Oct night] w.prog in [0, 1] for the current choice (Behavior.progress, from values already
    at hand: chebyshev to the target, s.live / o.hp, s.submitting, last turn's attack); join, hunt = walk; shop,
    heal, fall, hold = 0. pbest / pstall: the best so far and the rounds since it rose."""
    w.prog = min(1.0, max(0.0, BEH[w.cur[0]].progress(w, s, hit)))
    if w.prog > w.pbest + 1e-6:
        w.pbest, w.pstall = w.prog, 0
    else:
        w.pstall += 1


# ---- post pass ----
class ScanWard:
    """[B1 SCAN_WARD] P6 foreknowledge, P17 know the ground: after my move, my free ward (cooldown 10 [sdk 3.0.1
    WARD_COOLDOWN; was 1], one active, within 2, sees 6 [rules]) goes on a bush tile within 2 that my own sight does
    not cover. X3: the ward costs no gold, so cooldown 10 only caps it at one placement per 10 rounds; the goal-nearest
    rule below already places it ahead of me, where it stays useful while the cooldown runs. A ward on a bush tile sees its cluster [measured A60]; from outside nobody sees in [rules]. Among those,
    the one nearest my goal tile (none: farthest from spawn). My current ward's tile stays a candidate, so the ward
    moves only when a better tile comes into reach; no unseen bush within 2: it stays where it is. Counts placements
    (n) and enemies first seen through it (trace `sward spot`)."""
    __slots__ = ("bush", "pos", "n", "seen")

    def __init__(self):
        self.bush, self.pos, self.n, self.seen = None, None, 0, {}   # bush tiles, my ward, placements, enemy -> round seen

    @staticmethod
    def goal(w):
        """The tile my Behavior is heading for (group anchor, altar, spawn), or None."""
        op, tg = w.cur
        if op == "farm" and tg in w.G:
            return w.G[tg].anchor
        if op in ("bank", "hold") and tg is not None and tg < len(w.apos):
            return w.apos[tg]
        if op in ("shop", "heal"):
            return w.sp0
        return None

    def post(self, w, s):
        if self.bush is None:
            self.bush = game_map.bushes()
        if self.bush.is_empty():
            return
        me = w.me
        st = int(me.state())
        if not st & 1:
            return          # 08 G3: this turn rolled over into the round I died: position() is (-1, -1), the SDK raises
        if me.ward_cooldown() > 0:
            return
        p = me.position()
        c = me.ward_placement_tiles() & self.bush
        if not c.is_empty():
            aw = vision.ward_tiles(Team.ALLY)  # an ally's ward tile raises [measured]; my own stays a candidate
            if self.pos is not None:
                aw.set(self.pos, False)
            c = c & ~me.visible_tiles_from(p) & ~aw
        if not c.is_empty():
            gt = self.goal(w)
            fh = w.nav.F_home
            best, bk = None, None
            for q in c.positions():
                k = (q.chebyshev_distance(gt) if gt is not None else 0, -(fget(fh, q) if fh is not None else 0), q.x, q.y)
                if bk is None or k < bk:
                    best, bk = q, k
            # a recall / tribute started this turn: no acting [sdk]; 08 G3: stunned raises "cannot act" [measured]
            if best != self.pos and not st & 6 and not me.buffs().has_stun():
                try:
                    ok = me.place_ward(best)
                except Exception as e:
                    ok = False
                    trace("sward", f"err {best.x},{best.y} {err_text(e)}")
                if ok:
                    self.pos = best
                    self.n += 1
        if s.enemies and self.pos is not None:
            sv = me.visible_tiles_from(s.pos)   # my own sight when the enemies were sensed (before my move)
            for e in s.enemies:
                ep, k = e[1], int(e[0])
                if self.bush.is_set(ep) and not sv.is_set(ep):
                    if self.seen.get(k, -99) < s.r - 10:    # a new sighting after 10 rounds unseen
                        trace("sward", f"spot e{k} {ep.x},{ep.y} d={e[4]} ward={self.pos.x},{self.pos.y} {w.cur[0]}")
                    self.seen[k] = s.r


SCAN = ScanWard()

# ---- 70_updaters.py ----
"""Updaters (03_ARCHITECTURE.md section 2.3): SwUpdater.decide picks the Behavior each turn (R1: one updater, strat-sw's
choose). The opening seeds: every champion computes the same slot -> group list out of the draft record, with no
comms."""

SEED_UNTIL = 40             # [rule, 15 Oct ladder phase 1] the opening seed holds to this round (was round 1 + 2)


def opening_seed(w):
    """My entry of opening_slots (None past its end)."""
    slots = opening_slots(w, 6)               # 6 bodies at most: the same list whatever roster I saw at boot
    return slots[w.slot] if w.slot < len(slots) else None



def rich_group(w, m, used, tests):
    """[user plan 15 Oct, pair/trio opener] the richest reachable group not in used for m bodies: sides 0/1 before 2,
    then (gems + g2g(1) gold) / (d_us + clear rounds with m bodies); tests are need filters tried in order (the first
    that matches anything wins). None if nothing is reachable."""
    for ok in tests:
        best = None
        for h in w.order:
            o = w.G[h]
            if o.d_us >= 255 or h in used or not ok(o.need):
                continue
            cr = -(-sum(x[0] for x in o.mons) // (CHAMP_STR * m))
            key = (o.side > 1, -(o.gems + g2g(1) * o.gold) / (o.d_us + cr + 1), h)
            if best is None or key < best:
                best = key
        if best:
            return best[2]
    return None


GROUP_NAMES = {6: "six", 5: "five", 4: "quad", 3: "trio", 2: "pair", 1: "solo"}


def group_slots(w, r):
    """Stack seeds and subgroups. Before OPEN_END (06 section 4.1) the whole team is one subgroup on the richest group.
    After it, on a group map [user plan 15 Oct, pair/trio opener], the roster splits by size (5 -> trio + pair, 4 -> two
    pairs, 3 -> pair + solo, <= 2 -> one subgroup; 6 bodies with Cassi & Issac -> two trios). Subgroup 0 takes the richest group needing 2..its size (else >= 2,
    else any); a pair as subgroup 1 the next richest needing exactly 2 (else >= 2, else any); a solo the best need-1
    group (else any). The main carry's slot (06 section 3) joins the subgroup whose group has more gold (ties: subgroup 0); the other slots
    fill hers first, lowest slot first, then the other. Sets w.subs {slot: tuple of its subgroup's slots}; returns
    6 entries (slot -> group). Same on every champion: draft S (as bodies, nbody), roster order, draft records only."""
    S = min(6, max(1, nbody((w.d or {}).get("S") or 0) or len(w.roster)))
    sizes = (S,) if r < OPEN_END else (3, 3) if S >= 6 else (3, 2) if S == 5 else (2, 2) if S == 4 else (2, 1) if S == 3 else (S,)
    gs, used = [], set()
    for i, m in enumerate(sizes):
        if m == 1:
            tests = (lambda n: n <= 1, lambda n: True)
        elif i == 0:
            tests = (lambda n, m=m: 2 <= n <= m, lambda n: n >= 2, lambda n: True)
        else:
            tests = (lambda n: n == 2, lambda n: n >= 2, lambda n: True)
        g = rich_group(w, m, used, tests)
        gs.append(g)
        if g is not None:
            used.add(g)
    vs = w.main
    gold = [w.G[g].gold if g is not None else -1 for g in gs]
    iv = gold.index(max(gold)) if 0 <= vs < S else 0
    rest = [k for k in range(S) if k != vs] if 0 <= vs < S else list(range(S))
    mem = [[] for _ in sizes]
    if 0 <= vs < S:
        mem[iv].append(vs)
    for i in [iv] + [j for j in range(len(sizes)) if j != iv]:
        while len(mem[i]) < sizes[i] and rest:
            mem[i].append(rest.pop(0))
    w.subs = {}
    slots = [None] * 6
    for i, ms in enumerate(mem):
        for k in ms:
            w.subs[k] = tuple(sorted(ms))
            slots[k] = gs[i]
    return slots


def opening_slots(w, n):
    """n DISTINCT group handles (slot i takes entry i); every champion computes the same list with no comms.
    Groups on our side (0) and contested (1), ranked by the walk from our spawn (d_us; ties: higher value per round),
    solo groups (need 1) first, then pair groups (need 2). [rule, 15 Oct ladder 2] the main carry's slot first takes the
    nearest group with gold > 0 (one she can take alone if any: all gold to the main carry); no group is given to two slots (the
    50x50 4-pick ladder map had one seedable group and three champions on it); when the list runs out, the
    next-nearest unused reachable group of any need and side. Seeds only the first choice."""
    if stack_mode(w, cambc.round_number()):
        return group_slots(w, cambc.round_number())[:n]     # the team (open) or its subgroups (group map)
    solo, pair, rest = [], [], []
    for h in w.order:
        o = w.G[h]
        if o.d_us >= 255:
            continue
        hp = sum(m[0] for m in o.mons)
        cr = -(-hp // (CHAMP_STR * max(1, o.need)))
        key = (o.d_us, -(o.gems + g2g(1) * o.gold) / (o.d_us + cr + 1), h)
        (rest if o.side > 1 or o.need > 2 else solo if o.need <= 1 else pair).append(key)
    solo.sort()
    pair.sort()
    rest.sort()
    order = [k[2] for k in solo + pair + rest]
    vs = w.main
    vg = None
    if 0 <= vs < n:
        gold = sorted((w.G[h].side > 1, w.G[h].need > 1, w.G[h].d_us, h) for h in order if w.G[h].gold > 0)
        vg = gold[0][3] if gold else None
    slots, it = [], iter(h for h in order if h != vg)
    for i in range(n):
        slots.append(vg if i == vs and vg is not None else next(it, None))
    assert len(set(h for h in slots if h is not None)) == sum(1 for h in slots if h is not None), "seed dup"
    return slots


class SwUpdater:
    """R1's one updater (strat-sw's choose): price every option (50_prices price_all), drop the excluded ones, keep
    the current Behavior while the opening seed, the HOLD_TURNS hold, a chase hold or hysteresis says so, else start
    the best (World.start). Holds the opening seed and this turn's claims read from the slot bytes (lowcl / lowcn /
    lowsub: the claims of lower slots, read by the prices). retreat_now and flee_ok stay shared helpers."""
    __slots__ = ("seed", "seed_until", "claims", "lowcl", "lowcn", "lowsub")

    def __init__(self):
        self.seed, self.seed_until = None, 0    # opening seed (play_main) and the round it holds to
        self.claims, self.lowcl, self.lowcn, self.lowsub = {}, set(), {}, set()

    def seeded(self, w, s):
        """True while the opening seed holds: until SEED_UNTIL, while I still execute it (going), and the seeded group is
        not cleared / respawning (seen taken on arrival: Farm returns done) and no reward came in yet (bag or gold
        above what I held when it was set: a capture; a fast respawn otherwise kept me re-farming it). Clears seed and traces once on end."""
        sd = self.seed
        if sd is None:
            return False
        o = w.G.get(sd)
        if s.r <= self.seed_until and w.cur == ("farm", sd) and w.status == "going" and o is not None \
                and not (o.st == "resp" and o.until > s.r) and s.bag <= FARM.lastbag and s.gold <= FARM.lastgold:
            return True
        self.seed = None
        trace("choice", f"seed end {tname(w, 'farm', sd)} cur={w.cur[0]} status={w.status} st={o.st if o else '-'} "
                        f"bag={s.bag} gold={s.gold}")
        return False

    def decide(self, w, s):
        """Argmax with a HOLD_TURNS hold, then hysteresis; returns True when the choice changed.
        [rule, 15 Oct ladder 3] the HOLD_TURNS hold applies to HEAL too (ladder: heal/kill/heal/bank/heal dither with a
        44 bag); only retreat_now breaks it. Farm -> another farm needs the race row's farm_hyst, and the current job's
        price counts its sunk progress (SUNK_K). HEAL is never excluded (a death or timeout while healing must not forbid
        the next heal)."""
        cur = w.cur
        cl, by = Comms.claims(w, s)
        self.claims = cl
        self.lowcl = {w.idx[tg] for k, (op, tg) in by.items() if k < w.slot and op == 1 and tg in w.idx}
        self.lowcn = {}                                # group -> claimants with a lower slot than mine (one-way partners)
        for k, (op, tg) in by.items():
            if k < w.slot and op == 1 and tg in w.idx:
                self.lowcn[w.idx[tg]] = self.lowcn.get(w.idx[tg], 0) + 1
        if s.r >= OPEN_END and w.subs_r < OPEN_END:
            w.subs_r = s.r                             # the opening ends: subgroups on a group map, else none
            if group_map(w):
                group_slots(w, s.r)
            else:
                w.subs = {}
            trace("stack", f"open end subs={w.subs.get(w.slot)}")
        sb = getattr(w, "subs", None) or {}
        mine = sb.get(w.slot, ())
        self.lowsub = {w.idx[tg] for k, (op, tg) in by.items() if k < w.slot and k in mine and op == 1 and tg in w.idx}
        ps = price_all(w, s, cl, by)
        r = s.r
        ps = [t for t in ps if t[1] == "heal" or w.excl.get((t[1], t[2]), -1) <= r]
        ps.sort(key=lambda t: -t[0])
        curp = None
        for t in ps:
            if t[1] == cur[0] and t[2] == cur[1]:
                curp = t[0]
                break
        best = ps[0] if ps else (0.0, "fall", None)
        if best[0] <= 0:
            best = (0.0, "fall", None)
        if TRACE and s.attacker is not None and w.cur[0] in ("heal", "fall") or TRACE and s.attacker is not None and best[1] in ("heal", "fall"):
            trace("flee", f"{w.cur[0]}->{best[1]} att={int(s.attacker[0])} d={s.attacker[4]} trapped={int(s.trapped)} "
                          f"ok={int(flee_ok(s))} hp={s.hp / s.maxhp:.2f} pl={s.plose:.2f}")
        if self.seeded(w, s) and best[1] != "heal" and not retreat_now(s):
            return False                            # the opening seed holds (only HEAL / retreat break it)
        going = curp is not None and curp > 0 and w.status == "going"
        held = going and r - w.started < HOLD_TURNS and not retreat_now(s)
        # [user plan 15 Oct, ladder 5] a KILL on a still-visible target, or a HUNT on a fresh sighting while it prices,
        # holds for the phase's `chase` rounds (default 3) whatever its price, unless hp < 30 % or retreat_now (ladder:
        # Vesper chose a kill, stepped once, it priced negative and she dropped it, 4 times in one game)
        if (w.status == "going" and s.hp >= 0.3 * s.maxhp and not retreat_now(s)
                and r - w.started < ME["prof"].get("chase", 3)
                and ((cur[0] == "kill" and any(int(e[0]) == cur[1] for e in s.enemies))
                     or (cur[0] == "hunt" and curp is not None and cur[1] == s.sa and s.sc and s.sage <= SIGHT_FRESH))):
            held = True
        hy = HYST
        if cur[0] == "farm" and best[1] == "farm" and best[2] != cur[1]:
            hy = race(w)["farm_hyst"]
        if best[1] != "heal" and not retreat_now(s):
            hy = max(hy, 1.0 + SUNK_K * w.prog)     # [IMPROVEMENTS 2] sunk progress; HYST / farm_hyst stay the floor
        keep = held or (going and best[0] <= curp * hy) or \
               (cur[0] == "fall" and best[1] == "fall" and w.status == "going")
        if keep:
            return False
        new = (best[1], best[2])
        if new == cur and w.status == "going":
            return False
        hit, pg = w.hit, w.prog
        w.start(new, r, s)
        if TRACE:
            t2 = ps[1] if len(ps) > 1 else (0.0, "-", None)
            bfi = max((t[0] for t in ps if t[1] in ("kill", "hunt") or (t[1] == "join" and by.get(t[2], (0,))[0] == 3)),
                      default=0.0)
            trace("choice", f"{new[0]} {tname(w, new[0], new[1])} {best[0]:.2f} | {t2[1]} {tname(w, t2[1], t2[2])} "
                            f"{t2[0]:.2f} cur={curp if curp is None else round(curp, 2)} bag={s.bag} "
                            f"hp={s.hp / s.maxhp:.2f} fight={bfi:.2f} dcost={s.dcost:.0f} pl={getattr(s, 'plose', 0):.2f} ne={s.near_e} "
                            f"d={w.G[new[1]].anchor.chebyshev_distance(s.pos) if new[0] == 'farm' and new[1] in w.G else '-'} "
                            f"from={cur[0]}:{cur[1]} hit={int(hit)} prog={pg:.2f}"
                            + (f" roam={w.roam:.2f}" if new[0] == "hunt" and new[1] != s.sa else "")
                            + "".join(f" tp={e[1].x},{e[1].y} desp={min(e[1].chebyshev_distance(q) for q in w.esp.positions())}"
                                      for e in s.enemies if new[0] == "kill" and int(e[0]) == new[1]))
        return True


UPD = SwUpdater()

# ---- 80_draft.py ----
"""Draft-time map model (strat/README.md, step 1): the in-engine port of tools/mapmodel.py.

Same layers as the offline tool, computed under fuel (strat/FUEL_MODEL.md): every per-element Python operation
costs >= 500 fuel, Bitboard ops ~3k flat, bulk bytes/int ops 7-45 fuel per byte. So there is no per-tile Python:
whole-map work is DistanceFields, Bitboard ops and bytes slicing of the fields' raw u16 buffers (lo byte = distance;
fields are computed with max_distance 254, so a lo byte of 255 means unreached); Python loops run only over objects
(altars, groups, camps), path steps and the 10x10 cells. Rewritten 14 Oct (late) to fit draft turn 1.

Tags: [rules] GameRules.md, [measured] our matches, [model] a modelling choice (tunable, not a game fact).
Deviations from tools/mapmodel.py, all [model]:
  - distances >= 255 count as unreached (999 in the margin); only a > 254-step map is affected.
  - ownership: min of D over the camps' bounding box grown by 1 (offline: the exact Chebyshev-1 ring); when the
    box's first minimum is not on the ring, the exact ring is used. Same sides, margins and entries on all 9 maps.
  - nearest altar: exact (same descent rule as the offline): the altars within Chebyshev d+1 of the tile are
    found with 16-bit-lane int arithmetic; if one, it is the answer, else the descent runs until one is left.
  - blocks are the (nearest altar, side) keys of the groups and altars, not tile regions (st_blocks).
  - danger per cell is averaged over the cell's middle row, not all its tiles; the enemy-spawn zone is path
    distance D_them <= SPAWN_DANGER_R (offline: Chebyshev distance to a spawn tile).
  - enemy paths are traced only until they enter the enemy half (margin < 0) or merge into the traced tree:
    traffic on our half (margin >= 0) is exact; traffic and chokes on the enemy half are dropped.
  - no ward tiles (offline: WARDS): play never read them; the stage was deleted in session 3 (06), ScanWard places
    wards live (60_behaviors).
"""

R_REACT = 8                 # [model] reaction distance = vision 8 [rules]
RECALL = 5                  # recall channel [rules]
SPAWN_DANGER_R = 4          # [model]
DANGER_SPAN = 2 * R_REACT   # [model]
CHOKE_BUMP = 0.15           # [model]
NARROW_MAX = 0.6            # [model]
TRAFFIC_MIN_FRAC = 0.25     # [model]
CHAMP_STR, CHAMP_HP = 50, 1000   # generic champion (docs/ECONOMY.md farming rates: S 50)
KEEP_FRAC = 0.4             # [model] the hit body keeps >= 40% HP
TANK_SHARE = 0.6            # [user decision 15 Oct afternoon; guess] the most-hit body takes max(1/k, this) of the damage
SPREAD = True               # [model] monster hits shared evenly by the k bodies (False: all on one body)
DMAX = 254                  # fields' max_distance: the lo byte of the u16 is the distance, 255 = unreached
PROFILE = None              # measurement only: a custom stage order
SIDE_CH = "oct"             # ours, contested, theirs (u: unreachable)
DRAFT_RESERVE = 1_500_000   # never let a draft turn suspend: it would eat the next turn's pick

# object fields (alts and gobj are lists)
DU, DT, SD, EU, ET, HH, BD, NR, DA, BK = range(10)


def side_of(m):
    if m is None:
        return 3
    return 0 if m > R_REACT else 2 if m < -R_REACT else 1


def clear_damage(mons, k, S=CHAMP_STR):
    """Damage the k bodies take clearing a group with basic attacks (docs/ECONOMY.md, measured wolf row):
    all k hit the same monster, monsters die one at a time (highest Strength/HP first), overkill is lost;
    the whole group wakes on the first hit [rules L206] and every live monster hits from the round after our
    first hit, once per round [rules, measured A1]. Returns total damage."""
    r, dmg = 0, 0
    for hp, st in sorted(mons, key=lambda m: -m[1] / m[0]):
        r += -(-hp // int(k * S))
        dmg += st * (r - 1)
    return dmg


def tank(k):
    """[user decision 15 Oct afternoon] share of a clear's damage on the most-hit of k bodies: max(1/k, TANK_SHARE)."""
    return max(1.0 / max(1, k), TANK_SHARE)


def roster_stats(S):
    """[user decision 15 Oct afternoon] (mean Strength, mean HP) of the first S picks (ROSTER, base_stats in 20_champs: the SDK's 3.0 numbers, X2);
    CHAMP_STR / CHAMP_HP when unknown. [measured 15 Oct] min HP (Vendetta 800) made a lone wolf "need 2" and put
    collision into group mode (solo 0.70 -> 0.30); the mean keeps every public map in its bucket."""
    st = [v for v in (base_stats(d) for d in ROSTER[:max(1, S)]) if v]
    if not st:
        return CHAMP_STR, CHAMP_HP
    return sum(x[1] for x in st) / len(st), sum(x[0] for x in st) / len(st)


def bodies_needed(mons, S):
    """Smallest k in 1..S whose most-hit body keeps >= KEEP_FRAC of its HP; S + 1 if none does. [user decision 15 Oct
    afternoon] the roster's mean Strength / min HP (roster_stats), the most-hit body takes tank(k) of the damage."""
    rs, rh = roster_stats(S)
    for k in range(1, S + 1):
        d = clear_damage(mons, k, rs)
        if (d * tank(k) if SPREAD else d) <= (1 - KEEP_FRAC) * rh:
            return k
    return S + 1


def bodies_table(S=5):
    """Lines for the trace / report: composition -> k per load model."""
    W_, E_, G_, C_ = (1350, 20), (2400, 60), (5000, 120), (120, 0)   # wolf, elk, golem, cluster [sdk 3.0.1 base_stats]
    comps = (("lone wolf", [W_]), ("wolf pair", [W_, W_]), ("3-wolf pack", [W_, W_, W_]), ("elk", [E_]),
             ("elk pair", [E_, E_]), ("elk+3 cluster", [E_, C_, C_, C_]), ("golem", [G_]))
    out = []
    for name, m in comps:
        row = []
        for k in range(1, S + 1):
            d = clear_damage(m, k)
            row.append(f"{k}:{d}/{d // k}")
        g = globals()
        sp = g["SPREAD"]
        g["SPREAD"] = True
        a = bodies_needed(m, S)
        g["SPREAD"] = False
        b = bodies_needed(m, S)
        g["SPREAD"] = sp
        out.append(f"{name} spread={a} one={b} dmg(total/per-body) {' '.join(row)}")
    return out


def _sh(b, sx, sy):
    """Bitboard r with r(t) = b(t + s) in shift coordinates (tiles shifted off the map are dropped)."""
    if sx:
        b = b.shift_right(-sx)
    if sy:
        b = b.shift_up(-sy)
    return b


class DraftModel:
    """All draft state; stages run in order under the fuel guard, spilling to later draft turns."""

    def __init__(self):
        self.stages = ["geometry", "groups", "fields", "own", "altar", "blocks", "danger", "paths", "chokes"]
        if PROFILE:
            self.stages = PROFILE
        self.done = []
        self.cost = {}
        self.turn_of = {}
        self.gen = None
        self.unit = {}

    def est(self, name):
        """Fuel estimate of a stage [measured 14 Oct late, expanse 80x80 / lanes 90x30, padded ~1.5x]; N, G, A
        are known after geometry/groups."""
        N = getattr(self, "N", 10_000)
        G = len(getattr(self, "groups", ())) or 45
        A = len(getattr(self, "apos", ())) or 18
        return {"geometry": 150_000, "groups": 1_400_000 + 25_000 * G, "fields": 200_000 + 120 * N,
                "own": 100_000 + 30_000 * (G + A), "altar": 200_000 + 70 * N + 30_000 * G,
                "blocks": 100_000, "danger": 500_000, "paths": 200_000,
                "chokes": 600_000}.get(name, 1_000_000)

    def unit_hint(self, name):
        """Largest single unit of a generator stage before it is measured [padded]."""
        return {"paths": 400_000}.get(name, 400_000)

    def run(self, turn, reserve=DRAFT_RESERVE):
        """Run stages while they fit. A stage is a plain method (runs whole: needs its estimate up front) or a
        generator yielding after each unit of work: it runs unit by unit while the largest unit seen so far still
        fits above the reserve, and resumes on the next draft turn.
        Returns (stages finished this call, stages worked on this call)."""
        ran, touched = [], []
        while self.stages:
            s = self.stages[0]
            f0 = fuel()
            if self.gen is None:
                if f0 - reserve < self.est(s):
                    break
                try:
                    g = getattr(self, "st_" + s)()
                except Exception as e:
                    trace("model", f"stage={s} {err_text(e)}")
                    g = None
                self.gen = g if g is not None and hasattr(g, "send") else True
            done = self.gen is True
            if not done:
                unit = self.unit.get(s) or self.unit_hint(s)
                try:
                    while fuel() - reserve > unit:
                        u0 = fuel()
                        next(self.gen)
                        u = u0 - fuel()
                        if u > unit:
                            unit = self.unit[s] = u
                except StopIteration:
                    done = True
                except Exception as e:
                    trace("model", f"stage={s} {err_text(e)}")
                    done = True
            self.cost[s] = self.cost.get(s, 0) + f0 - fuel()
            self.turn_of.setdefault(s, []).append(turn)
            touched.append(s)
            if not done:
                break
            self.gen = None
            self.stages.pop(0)
            self.done.append(s)
            ran.append(s)
            trace("stage", f"{s} turns={'+'.join(map(str, self.turn_of[s]))} fuel={self.cost[s]} "
                           f"unit={self.unit.get(s, '-')} left={fuel()}")
        return ran, touched

    # ---- stages
    def st_geometry(self):
        self.W, self.H = W, H = game_map.width(), game_map.height()
        self.N = W * H
        self.S = max(1, int(cambc.draft.team_size()))
        self.walls, self.holes = game_map.walls(), game_map.holes()
        self.altar_bb = game_map.altars()
        self.terr = self.walls | self.holes | self.altar_bb       # can't be entered [rules]
        self.sp = game_map.spawn_region(Team.ALLY)
        self.esp = game_map.spawn_region(Team.ENEMY)
        self.us = self.sp.positions()          # positions() order, as the offline dump
        self.them = self.esp.positions()
        self.apos = self.altar_bb.positions()  # altar id = positions() order (as the offline dump)
        self.F = ~Bitboard()                   # the whole map (off-map tests for chokes)
        trace("geom", f"{W}x{H} S={self.S} altars={len(self.apos)} us={len(self.us)} full={self.F.count()}")

    def st_groups(self):
        """Per camp only kind() (base_stats memoised per kind), spawn_position() and x/y; camp tiles are set one
        by one into the live-camp block; a bounding box per group for st_own."""
        self.groups = []           # (handle, x0, y0, x1, y1, ((x, y), ...) camps, bodies)
        stats = {}
        memo = {}
        cbb = Bitboard()
        S = self.S
        n1 = gtot = g2 = 0                         # game type [user plan 15 Oct, game type]: solo share, group gems
        for g in game_map.camp_groups():           # the only call (~0.94M) [measured]
            mons = []
            cs = []
            for c in g.camps():
                k = int(c.kind())
                st = stats.get(k)
                if st is None:
                    b = c.base_stats()             # max_health()/strength() raise in the draft [measured]
                    st = stats[k] = (int(b.base_health), int(b.base_strength))
                mons.append(st)
                p = c.spawn_position()
                cbb.set(p)
                cs.append((p.x, p.y))
            key = tuple(sorted(mons))
            bd = memo.get(key)
            if bd is None:
                bd = memo[key] = bodies_needed(list(key), S)
            try:
                gv = int(g.gem_value())
            except Exception:
                gv = 0
            n1 += bd == 1
            gtot += gv
            if bd >= 2:
                g2 += gv
            if len(cs) == 1:
                x, y = cs[0]
                self.groups.append((int(g), x, y, x, y, cs, bd))
            else:
                xs = [c[0] for c in cs]
                ys = [c[1] for c in cs]
                self.groups.append((int(g), min(xs), min(ys), max(xs), max(ys), cs, bd))
        ng = len(self.groups)
        # [user plan 15 Oct, game type] solo = groups needing 1 body / all groups (any side); ggems = share of all
        # groups' gems in groups needing >= 2. Bytes 14 / 15 of the header, 0-255 (255 = 1.0, also "unknown")
        self.solo = n1 / ng if ng else 1.0
        self.ggems = g2 / gtot if gtot else 0.0
        trace("game", f"solo={self.solo:.2f} ({n1}/{ng}) ggems={self.ggems:.2f} ({g2}/{gtot})")
        self.block = self.terr | cbb               # live camps block movement [sdk]
        self.free = ~self.block

    def st_fields(self):
        f = self.Fus = DistanceField()
        f.compute((self.block | self.esp) & ~self.sp, self.sp, Bitboard(), DMAX)
        f = self.Fth = DistanceField()
        f.compute((self.block | self.sp) & ~self.esp, self.esp, Bitboard(), DMAX)
        self.Ru = bytes(self.Fus.export_linear_buffer())   # u16 little-endian, index y*W+x [measured]: lo byte = D (export_raw_buffer is chunked, not row-major)
        self.Rt = bytes(self.Fth.export_linear_buffer())

    def boxmin(self, R, x0, y0, x1, y1):
        """(min lo byte, its tile index) over the box (clamped to the map), lowest row-major index on ties."""
        W = self.W
        x0 = x0 if x0 > 0 else 0
        y0 = y0 if y0 > 0 else 0
        x1 = x1 if x1 < W - 1 else W - 1
        y1 = y1 if y1 < self.H - 1 else self.H - 1
        w = x1 - x0 + 1
        a = 2 * (y0 * W + x0)
        s = b"".join([R[o:o + 2 * w:2] for o in range(a, 2 * (y1 * W + x0) + 1, 2 * W)])
        m = min(s)
        k = s.find(m)
        return m, (y0 + k // w) * W + x0 + k % w

    def ringmin(self, R, cs):
        """Exact ring min over the camps' 3x3 boxes (lowest index on ties)."""
        best = (256, -1)
        for x, y in cs:
            v = self.boxmin(R, x - 1, y - 1, x + 1, y + 1)
            if v < best:
                best = v
        return best

    def classify(self, x0, y0, x1, y1, cs):
        """[d_us, d_them, side, e_us, e_th] from the box minima of both fields (see the docstring)."""
        W = self.W
        res = []
        for R in (self.Ru, self.Rt):
            m, e = self.boxmin(R, x0 - 1, y0 - 1, x1 + 1, y1 + 1)
            if m == 255:
                res += (FAR, None)
                continue
            if cs is not None:
                ex, ey = e % W, e // W
                for x, y in cs:
                    if -1 <= x - ex <= 1 and -1 <= y - ey <= 1:
                        break
                else:
                    m, e = self.ringmin(R, cs)
            res += (m, e)
        mu, eu, mt, et = res
        if mu == FAR and mt == FAR:
            return [FAR, FAR, 3, None, None]
        m = (mt if mt < FAR else 999) - (mu if mu < FAR else 999)
        return [mu, mt, 0 if m > R_REACT else 2 if m < -R_REACT else 1, eu, et]

    def st_own(self):
        S = self.S
        self.alts = [self.classify(a.x, a.y, a.x, a.y, None) for a in self.apos]
        self.gobj = []
        for h, x0, y0, x1, y1, cs, bd in self.groups:
            o = self.classify(x0, y0, x1, y1, cs if len(cs) > 1 else None)
            o += (h, bd, 255, FAR, 255)
            self.gobj.append(o)
        ca = [0, 0, 0, 0]
        cg = [0, 0, 0, 0]
        for o in self.alts:
            ca[o[SD]] += 1
        for o in self.gobj:
            cg[o[SD]] += 1
        self.ca, self.cg = ca, cg
        # Regime on ALTARS by side vs team size S [model, corrected 14 Oct]:
        #   few  : ours + contested <= 2 and contested >= ours   (one or two banks, shared: group up, fight)
        #   many : ours >= S                                       (a safe altar per body)
        #   pick : otherwise
        if ca[0] + ca[1] <= 2 and ca[1] >= ca[0]:
            self.regime = 0
        elif ca[0] >= S:
            self.regime = 2
        else:
            self.regime = 1
        self.bank = 0 if ca[0] else 1 if ca[1] else 2
        self.rich = cg[0] + cg[1]           # richness = rich / S groups (ours + contested) per body

    def label(self, e, d):
        """Nearest altar of tile index e at all-altar distance d (< FAR), as the offline descent_label(): descend
        the all-altar field (next_move_from: first optimal step in compass order [sdk]) to a ring tile, then the
        lowest altar id adjacent to it. The final altar lies within Chebyshev d+1 of e, so when only one altar
        does, it is the answer without descending; else descend until one candidate is left (or the ring)."""
        W = self.W
        x, y = e % W, e // W
        ONES = self.ONES
        r = d + 1
        dx = self.AXL + (r + 0x4000 - x) * ONES        # lanes ax - x + r + 0x4000
        dy = self.AYL + (r + 0x4000 - y) * ONES
        k2 = (2 * r + 1) * ONES
        c = dx & ~(dx - k2) & dy & ~(dy - k2) & self.B14  # bit 14 of lane k: |ax - x| <= r and |ay - y| <= r
        if c & (c - 1) == 0:
            return (c.bit_length() - 15) >> 4 if c else 255
        if d == 0:
            return ((c & -c).bit_length() - 15) >> 4
        C = []
        while c:
            lo = c & -c
            C.append((lo.bit_length() - 15) >> 4)
            c ^= lo
        AX, AY = self.AX, self.AY
        nm = self.Fa.next_move_from
        t = V(x, y)
        while True:
            dd = nm(t)
            if dd is None:
                break
            t = t + dd
            d -= 1
            x, y = t.x, t.y
            r = d + 1
            C = [k for k in C if -r <= AX[k] - x <= r and -r <= AY[k] - y <= r]
            if len(C) == 1 or d == 0:
                break
        return C[0] if C else 255        # d == 0: C = adjacent altars in id order -> the lowest id

    def st_altar(self):
        """One DistanceField from every altar's approach ring (Chebyshev 1, walkable), as the offline altar BFS:
        distance to the nearest altar (d_alt); labels by label()."""
        roots = Bitboard()
        for a in self.apos:
            roots.draw_chebyshev(a, 1)
        roots &= self.free
        f = self.Fa = DistanceField()
        f.compute(self.block & ~roots, roots, Bitboard(), DMAX)
        Ra = bytes(f.export_linear_buffer())
        self.AX = [a.x for a in self.apos]
        self.AY = [a.y for a in self.apos]
        ONES = AXL = AYL = 0
        for k in range(len(self.apos)):
            ONES |= 1 << 16 * k
            AXL |= self.AX[k] << 16 * k
            AYL |= self.AY[k] << 16 * k
        self.ONES, self.AXL, self.AYL, self.B14 = ONES, AXL, AYL, ONES << 14
        W = self.W
        a0, s0 = FAR, None
        for p in self.us:                         # spawn -> its nearest altar (first spawn tile at the min)
            i = p.y * W + p.x
            v = Ra[2 * i]
            if v < a0:
                a0, s0 = v, i
        self.a0 = a0 if a0 < 255 else FAR
        self.spawn_altar = self.label(s0, a0) if self.a0 < FAR else 255
        for o in self.gobj:
            e = o[EU] if o[DU] < FAR else o[ET]
            if e is None:
                continue
            v = Ra[2 * e]
            if v < 255:
                o[NR], o[DA] = self.label(e, v), v

    def st_blocks(self):
        """Blocks = (nearest altar, side) of the groups' entry tiles, plus each altar's own (altar, side).
        Recall flag = majority of the block's groups whose entry is more than RECALL + a0 from its altar;
        traffic = enemy paths traced to the block's objectives. [model] (offline blocks are tile regions)."""
        keys = {}
        lim = RECALL + self.a0
        for a, o in enumerate(self.alts):
            if o[SD] < 3:
                keys[a * 4 + o[SD]] = [0, 0, 1 if o[SD] < 2 and o[DT] < FAR else 0]
        for o in self.gobj:
            if o[NR] == 255:
                continue
            k = o[NR] * 4 + o[SD]
            b = keys.get(k)
            if b is None:
                b = keys[k] = [0, 0, 0]
            b[0] += 1
            if lim < o[DA] < FAR:
                b[1] += 1
            if o[SD] < 2 and o[DT] < FAR:
                b[2] += 1
        order = sorted(keys)
        self.blocks = [(k >> 2, k & 3, 1 if keys[k][1] * 2 > keys[k][0] else 0, keys[k][2]) for k in order]
        bid = {k: n for n, k in enumerate(order)}
        for o in self.gobj:
            if o[NR] != 255:
                o[BK] = bid.get(o[NR] * 4 + o[SD], 255)

    def st_danger(self):
        """Static danger per 10x10 cell (as the offline danger_grid: 1 within SPAWN_DANGER_R of the enemy
        spawn, 0.5 - clamp(margin, +-16)/32 elsewhere, + CHOKE_BUMP on chokes, 0 where neither side reaches),
        averaged over the non-terrain tiles of ONE sampled row per cell (its middle row) [model]. The margins
        of the sampled rows come from 16-bit-lane arithmetic on Python ints."""
        W, H = self.W, self.H
        rows = [(cy * H // GRID + (cy + 1) * H // GRID) // 2 for cy in range(GRID)]
        n = GRID * W
        Rt, Ru = self.Rt, self.Ru
        t = b"".join([Rt[2 * y * W:2 * (y + 1) * W:2] for y in rows])      # lo bytes: D_them, 255 unreached
        u = b"".join([Ru[2 * y * W:2 * (y + 1) * W:2] for y in rows])
        TB = self.terr.export_linear_buffer()     # bit i = tile i, LSB first
        mask = (1 << W) - 1
        ts = []
        I = int.from_bytes
        for y in rows:                            # terrain chars of the sampled rows: b'1' terrain
            b0 = y * W
            v = I(TB[b0 >> 3:(b0 + W + 7) >> 3], "little") >> (b0 & 7) & mask
            ts.append(bin(v | 1 << W)[:2:-1])
        ts = "".join(ts).encode()
        bt = bytearray((128,)) * (2 * n)                 # lane = 0x8000 + t
        bt[0::2] = t
        bu = bytearray(2 * n)
        bu[0::2] = u
        x = (I(bt, "little") - I(bu, "little")).to_bytes(2 * n, "little")    # lanes 0x8000 + m
        lo, hi = x[0::2], x[1::2]                         # hi 0x80: m = lo; hi 0x7F: m = lo - 256
        p = I(lo.translate(_T_POS), "little")
        q = I(lo.translate(_T_NEG), "little")
        sg = I(hi.translate(_T_SIGN), "little")
        un = I(t.translate(_T_FF), "little") & I(u.translate(_T_FF), "little")  # neither side reaches
        spz = I(t.translate(_T_SPZ), "little")          # enemy spawn zone (path distance)
        c = ((p ^ ((p ^ q) & sg)) | un) & ~spz
        dz = c.to_bytes(n, "little").translate(_T_DANGER)    # danger x32, unreached 0, spawn zone 32
        dz = (I(dz, "little") & I(ts.translate(_T_WALK), "little")).to_bytes(n, "little")  # terrain: 0
        xs = [cx * W // GRID for cx in range(GRID + 1)]
        tot, cnt = [], []
        for k in range(GRID):
            b = k * W
            for cx in range(GRID):
                a0, a1 = b + xs[cx], b + xs[cx + 1]
                tot.append(sum(dz[a0:a1]))
                cnt.append(ts.count(48, a0, a1))
        self.dz, self.drows, self.dtot, self.dcnt = dz, rows, tot, cnt
        self.danger_cells()

    def danger_cells(self):
        """Cell means from the sampled sums (+ CHOKE_BUMP for chokes on sampled tiles, once chokes ran),
        quantised 0..14 (15 = no non-terrain sampled tile)."""
        W, GR = self.W, GRID
        tot = self.dtot[:]
        rows = self.drows
        for i in getattr(self, "choke", {}):
            y = i // W
            if y in rows:
                k = rows.index(y)
                v = self.dz[k * W + i % W]
                if v < 32:
                    tot[k * GR + (i % W) * GR // W] += min(32, v + CHOKE_BUMP * 32) - v
        self.danger = [15 if m == 0 else int(s / (32 * m) * 14 + 0.5) for s, m in zip(tot, self.dcnt)]

    def st_paths(self):
        """Enemy shortest paths (descending D_them, compass order) from the entry of every ours/contested
        objective, stopped where they enter the enemy half (margin < 0; margin never rises along a path) or merge
        into the tree traced so far. Traffic by push-down over merge events, path by path in reverse creation
        order: along a path it is constant between merges and never falls, so each path is a few segments.
        Plane (Bitboard) PT: tree tiles with traffic >= traffic_min (st_chokes)."""
        W, N = self.W, self.N
        Ru, Rt = self.Ru, self.Rt
        nm = self.Fth.next_move_from
        own = [-1] * N                            # tile -> path id << 12 | position
        paths = []                                # (indices, Vec2s, merge code)
        extra = []                                # starts on tiles already in the tree
        starts = 0
        for o in self.alts + self.gobj:
            if o[SD] > 1 or o[DT] >= FAR:
                continue
            i = o[ET]
            starts += 1
            if own[i] >= 0:
                extra.append(own[i])
                continue
            pid = len(paths) << 12
            pi, pv = [], []
            tgt, n = -1, 0
            t = V(i % W, i // W)
            while True:
                own[i] = pid | n
                pi.append(i)
                pv.append(t)
                if Rt[2 * i] < Ru[2 * i]:
                    break
                d = nm(t)
                if d is None:
                    break
                t = t + d
                i = t.y * W + t.x
                n += 1
                if own[i] >= 0:
                    tgt = own[i]
                    break
            paths.append((pi, pv, tgt))
            yield
        tmin = max(2, -(-starts // 4))
        inflow = [[] for _ in paths]
        for c in extra:
            inflow[c >> 12].append((c & 4095, 1))
        PT = self.PT = Bitboard()
        for pid in range(len(paths) - 1, -1, -1):
            pi, pv, tgt = paths[pid]
            ev = inflow[pid]
            if len(ev) > 1:
                ev.sort()
            ev.append((len(pi), 0))
            v, a = 1, 0
            for pos, amt in ev:
                if pos > a:
                    if v >= tmin:
                        for q in pv[a:pos]:
                            PT.set(q)
                    a = pos
                v += amt
            if tgt >= 0:
                inflow[tgt >> 12].append((tgt & 4095, v))
        self.paths = paths
        self.npaths = starts
        self.traffic_min = tmin
        self.tree = sum(len(p[0]) for p in paths)

    def pinched(self, blk):
        """[model, as the offline pinched()] Bitboard of tiles with a blocked tile within 2 steps on BOTH sides
        along a row, a column or a diagonal (off-map counts as blocked). ~50 Bitboard ops."""
        off = self.off2
        out = None
        for ax, ay in ((1, 0), (0, 1), (1, 1), (1, -1)):
            r = None
            for sx, sy in ((ax, ay), (-ax, -ay)):
                y1 = blk | _sh(blk, sx, sy)
                ray = _sh(y1, sx, sy) | off[(sx, sy)]
                r = ray if r is None else r & ray
            out = r if out is None else out | r
        return out

    def st_chokes(self):
        """Choke = busy (traffic >= traffic_min) tree tile that is pinched (whole-map Bitboard) and narrow (walkable
        share of the in-map 5x5 window <= NARROW_MAX); 1 if it stays a choke with the camps cleared (terrain
        only), else 2. Adds the choke bump to the danger grid."""
        F = self.F
        off = {}
        for sx, sy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            off[(sx, sy)] = F & ~_sh(F, 2 * sx, 2 * sy)
        for sx in (1, -1):
            for sy in (1, -1):
                off[(sx, sy)] = off[(sx, 0)] | off[(0, sy)]
        self.off2 = off
        W, H = self.W, self.H
        cand = (self.pinched(self.block) & self.PT).positions()
        cl = []
        for p in cand:
            x, y = p.x, p.y
            n = (min(W, x + 3) - max(0, x - 2)) * (min(H, y + 3) - max(0, y - 2))
            b = Bitboard()
            b.draw_chebyshev(p, 2)
            if round((b & self.free).count() / n, 2) <= NARROW_MAX:
                cl.append((p, b, n, y * W + x))
        self.choke = {}
        if cl:
            pt = self.pinched(self.terr)
            ft = ~self.terr
            for p, b, n, i in cl:
                self.choke[i] = 1 if (round((b & ft).count() / n, 2) <= NARROW_MAX and pt.is_set(p)) else 2
        self.ncand = len(cand)
        if hasattr(self, "dtot"):
            self.danger_cells()                      # add the choke bump to the danger grid

    # ---- encode (layout: decode() below)
    def encode(self):
        """Draft memory bytes, built as one int list."""
        A = getattr(self, "alts", [])
        G = getattr(self, "gobj", [])
        B = getattr(self, "blocks", [])
        done = self.done
        fl = 0
        for bit, s in enumerate(("own", "altar", "paths", "chokes", "", "blocks", "danger")):
            if s in done:
                fl |= 1 << bit
        if not self.stages:
            fl |= 128
        out = [MEM_VERSION, getattr(self, "W", 0), getattr(self, "H", 0), getattr(self, "S", 0),
               getattr(self, "regime", 3) | getattr(self, "bank", 3) << 2, getattr(self, "spawn_altar", 255), fl,
               len(A), len(G), len(B), 0, min(255, getattr(self, "rich", 0)), min(255, getattr(self, "a0", 255)),
               min(255, getattr(self, "traffic_min", 0)), round(255 * getattr(self, "solo", 1.0)),
               round(255 * getattr(self, "ggems", 0.0))]
        for a, p in zip(A, self.apos):
            out += (a[SD], p.x, p.y)
        for o in G:
            out += (o[HH] & 255, o[SD] | (o[BD] if o[BD] < 15 else 15) << 2, o[BK], o[NR],
                    o[DU] if o[DU] < 255 else 255, o[DT] if o[DT] < 255 else 255)
        for alt, sd, rc, tr in B:
            out += (alt & 255, sd | rc << 2, tr if tr < 255 else 255)
        q = getattr(self, "danger", None)
        if q is not None:
            out += [q[k] | q[k + 1] << 4 for k in range(0, GRID * GRID, 2)]
        return bytes(out[:cambc.constants.DRAFT_MEMORY_BYTES])


_T_POS = bytes(16 + min(v, 16) for v in range(256))          # m = v >= 0
_T_NEG = bytes(max(0, v - 240) for v in range(256))          # m = v - 256 < 0
_T_SIGN = bytes(255 if v == 0x7F else 0 for v in range(256))
_T_FF = bytes(255 if v == 255 else 0 for v in range(256))
_T_SPZ = bytes(255 if v <= SPAWN_DANGER_R else 0 for v in range(256))
_T_WALK = bytes(255 if v == 48 else 0 for v in range(256))
_T_DANGER = bytes(0 if v > 32 else 32 - v for v in range(256))


# ---- the draft entry (was 90_main's draft branch) ----
# Draft memory: submit() raises once pick() was called in the same turn (engine error 18 on later turns; on turn 1
# "Memory access requires the owning team's input boundary") [measured 14 Oct, bots/_bench]. So turn 1 picks,
# then models and encodes; every later turn submits the bytes encoded so far (~30k fuel) immediately before its
# pick, then continues the model. The champions read the last submit [measured]. Work done on the last draft turn
# is never submitted, so every stage must finish before it.

# ChampionDraft values [sdk]: RYTH 0, VESPER_VALE 1, VARG 9, REN 8, MARCELLA 6, VENDETTA 2; others as backup, Heart of
# Ruin (11, new in 3.0: 1000 HP / 40 Str melee, up to +50 % damage at low HP [sdk]) first (X6; GUESS its rank).
# The first S picks play: Ren third (06 section 11.2), so he is the second carry at every team size.
PICKS = (9, 1, 8, 0, 2, 6)
BACKUP = PICKS + (11,) + tuple(d for d in range(11) if d not in PICKS)
LATE_RESERVE = 700_000      # later draft turns: the pick and submit are done first; keep room for encode


def do_pick():
    try:
        ours = [int(p) for p in cambc.draft.current_draft(Team.ALLY)]
        p = next((d for d in BACKUP if d not in ours), PICKS[0])
        cambc.draft.pick(p)
        return p
    except Exception as e:
        trace("draft", "pick " + err_text(e))
        return None


def draft_main():
    try:
        _TAG[0] = f"{'AB'[cambc._bc.my_team()]}|draft"
    except Exception:
        pass
    dm = None
    data = None
    turn = 0
    while True:
        turn += 1
        f_start = fuel()
        sub = "-"
        if data is not None:
            try:
                cambc.draft_memory.submit(data)    # before the pick (see the docstring)
                sub = str(len(data))
            except Exception as e:
                sub = err_text(e)
        picked = do_pick()
        ran = touched = []
        try:
            if dm is None:
                dm = DraftModel()
                if turn == 1 and TRACE:
                    for line in bodies_table(5):
                        trace("bodies", line)
            ran, touched = dm.run(turn, DRAFT_RESERVE if turn == 1 else LATE_RESERVE)
            if ran or data is None:
                f0 = fuel()
                data = dm.encode()
                trace("stage", f"encode turn={turn} fuel={f0 - fuel()} bytes={len(data)}")
        except Exception as e:
            trace("draft", err_text(e))
        trace("draft", f"turn={turn} start={f_start} picked={picked} submitted={sub} ran={','.join(ran)} worked={','.join(touched)} "
                       f"pending={','.join(dm.stages) if dm else '?'} used={f_start - fuel()} left={fuel()}")
        cambc.end_turn()
